1	/**
2	 * The whole screen: the launchpad, and the map you open from it.
3	 *
4	 * Two states and nothing in between. The launchpad names the two ways into the
5	 * tool and offers the four examples from the brief; opening the one that is
6	 * built swaps the page for the map. Everything on the map came over the wire
7	 * from the server, and the line under it says which address it came from — this
8	 * product does not put a number on screen that a reader cannot trace to an
9	 * input, a rule or a source, and that includes numbers a stored example happens
10	 * to carry.
11	 *
12	 * There is no spinner anywhere, and there never will be. A spinner says "wait"
13	 * without saying what for. While something is on its way the screen says what
14	 * it is waiting for and where it asked.
15	 */
16	
17	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
18	import { branchAnnouncement } from "./a11y/announcement";
19	import { outlineOf } from "./a11y/sentences";
20	import type { About, FixtureSummary, Health, Readiness } from "./api/client";
21	import { readAbout, readExampleList, readHealth, readReadiness } from "./api/client";
22	import { BranchPanel, InterventionPanel } from "./components/BranchPanel";
23	import { type Command, CommandPalette } from "./components/CommandPalette";
24	import { DeltaRail } from "./components/DeltaRail";
25	import { Inspector } from "./components/Inspector";
26	import { Launchpad } from "./components/Launchpad";
27	import { Outline } from "./components/Outline";
28	import { ShortcutsSheet } from "./components/ShortcutsSheet";
29	import { MapCanvas } from "./graph/Canvas";
30	import { bothPaintings } from "./graph/diff/branchWorld";
31	import { endings, NO_SUMMARY_YET } from "./graph/diff/endings";
32	import { tileHeight } from "./graph/geometry";
33	import type { MapKeys } from "./keyboard/useMapKeys";
34	import {
35	  appendEdit,
36	  type BranchView,
37	  branchesOf,
38	  type Edit,
39	  FixtureWorldSource,
40	  forkBranch,
41	  openBranch,
42	  type Selection,
43	  type WorldSource,
44	  type WorldView,
45	  workshopOf,
46	} from "./world";
47	
48	/**
49	 * Everything the screen can know about one thing it asked for. Three states and
50	 * no others, which is what makes every pixel below traceable to a cause.
51	 */
52	type Answer<Reading> =
53	  | { state: "asking" }
54	  | { state: "answered"; value: Reading }
55	  | { state: "failed"; reason: string };
56	
57	/** How loud a row's words are. Emphasis only — the words carry the meaning. */
58	type Tone = "good" | "quiet" | "loud";
59	
60	/** One row of the strip at the foot of the launchpad. */
61	interface Reading {
62	  /** What is being reported, such as "server". */
63	  label: string;
64	  /** The value from the server, or null while the request is still in flight. */
65	  value: string | null;
66	  /** A mark beside the words. Never the only carrier of meaning. */
67	  glyph: string;
68	  /** What the value means, in plain words. On a failure, this is the failure. */
69	  state: string;
70	  tone: Tone;
71	}
72	
73	/** Turn whatever a failed request threw into one sentence. */
74	function inWords(reason: unknown): string {
75	  return reason instanceof Error ? reason.message : "The reason was not recorded.";
76	}
77	
78	/**
79	 * Make one request when the screen first appears and report where it got to.
80	 *
81	 * @param ask The request to make. It must be the same function on every render,
82	 *   so pass one defined at module level rather than one written inline.
83	 */
84	function useAnswer<Reading>(ask: () => Promise<Reading>): Answer<Reading> {
85	  const [answer, setAnswer] = useState<Answer<Reading>>({ state: "asking" });
86	
87	  useEffect(() => {
88	    let stillOnScreen = true;
89	    ask().then(
90	      (value) => {
91	        if (stillOnScreen) {
92	          setAnswer({ state: "answered", value });
93	        }
94	      },
95	      (reason: unknown) => {
96	        if (stillOnScreen) {
97	          setAnswer({ state: "failed", reason: inWords(reason) });
98	        }
99	      },
100	    );
101	    return () => {
102	      stillOnScreen = false;
103	    };
104	  }, [ask]);
105	
106	  return answer;
107	}
108	
109	/** The row that says whether the server answered at all. */
110	function serverReading(answer: Answer<Health>): Reading {
111	  switch (answer.state) {
112	    case "asking":
113	      return {
114	        label: "server",
115	        value: null,
116	        glyph: "○",
117	        state: "asking the server",
118	        tone: "quiet",
119	      };
120	    case "answered":
121	      return {
122	        label: "server",
123	        value: answer.value.status,
124	        glyph: "●",
125	        state: "reachable",
126	        tone: "good",
127	      };
128	    case "failed":
129	      return { label: "server", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
130	  }
131	}
132	
133	/** The row that says whether a key for the language model is configured. */
134	function modelKeyReading(answer: Answer<Readiness>): Reading {
135	  switch (answer.state) {
136	    case "asking":
137	      return {
138	        label: "model key",
139	        value: null,
140	        glyph: "○",
141	        state: "asking the server",
142	        tone: "quiet",
143	      };
144	    case "answered":
145	      return answer.value.model_key_present
146	        ? {
147	            label: "model key",
148	            value: "present",
149	            glyph: "●",
150	            state: "ready to generate",
151	            tone: "good",
152	          }
153	        : {
154	            label: "model key",
155	            value: "absent",
156	            glyph: "○",
157	            state: "no key configured — generating a map is not built yet",
158	            tone: "quiet",
159	          };
160	    case "failed":
161	      return { label: "model key", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
162	  }
163	}
164	
165	/** The row that says which build answered. */
166	function versionReading(answer: Answer<About>): Reading {
167	  switch (answer.state) {
168	    case "asking":
169	      return {
170	        label: "version",
171	        value: null,
172	        glyph: "○",
173	        state: "asking the server",
174	        tone: "quiet",
175	      };
176	    case "answered":
177	      return {
178	        label: "version",
179	        value: answer.value.version,
180	        glyph: "●",
181	        state: `reported by ${answer.value.name}`,
182	        tone: "good",
183	      };
184	    case "failed":
185	      return { label: "version", value: "—", glyph: "○", state: answer.reason, tone: "loud" };
186	  }
187	}
188	
189	/**
190	 * Why the three examples that need the model are not live, in one sentence.
191	 *
192	 * Read from the server's own answer rather than written into the page, so that
193	 * the reason on screen is the real one.
194	 */
195	function notLiveReason(answer: Answer<Readiness>): string {
196	  if (answer.state === "answered" && !answer.value.model_key_present) {
197	    return "Turning your own words into a map needs the model, and this server has no key for one.";
198	  }
199	  return "Turning your own words into a map is not built yet.";
200	}
201	
202	/**
203	 * One row: a label, the value the server gave, and what that value means.
204	 *
205	 * While the value is missing the cell holds a bar of the same height, so the
206	 * row does not change size when the answer arrives. There is no spinner: a bar
207	 * where the value will land says the same thing without pretending to spin.
208	 */
209	function StatusRow({ reading }: { reading: Reading }) {
210	  const waiting = reading.value === null;
211	  return (
212	    <div className="status-row">
213	      <dt className="status-label">{reading.label}</dt>
214	      <dd className="status-value" data-settled={waiting ? "no" : "yes"}>
215	        {waiting ? <span className="placeholder" aria-hidden="true" /> : reading.value}
216	      </dd>
217	      <dd className="status-state" data-tone={reading.tone}>
218	        <span className="glyph" aria-hidden="true">
219	          {reading.glyph}
220	        </span>
221	        <span className="state-words">{reading.state}</span>
222	      </dd>
223	    </div>
224	  );
225	}
226	
227	/** Which of the two screens is showing. */
228	type Screen =
229	  | { at: "launchpad" }
230	  | { at: "opening"; id: string }
231	  | { at: "map"; world: WorldView; branches: readonly BranchView[] }
232	  | { at: "failed"; id: string; reason: string };
233	
234	/** How long the wires take to arrive, column by column, before the map settles. */
235	const WAVE_SETTLES_AFTER = 1200;
236	
237	/**
238	 * The map, the panel beside it, and everything you can do to both.
239	 *
240	 * Three things live here rather than inside the map, because all three are about
241	 * the whole screen rather than about the picture: which branch is open, which of
242	 * the two worlds is painted, and what the keyboard is on.
243	 */
244	function MapScreen({
245	  base,
246	  branches,
247	  onLeave,
248	}: {
249	  base: WorldView;
250	  branches: readonly BranchView[];
251	  onLeave: () => void;
252	}) {
253	  const [shop, setShop] = useState(() => workshopOf(branches));
254	  const [showing, setShowing] = useState<"now" | "before">("now");
255	  const [selection, setSelection] = useState<Selection>(null);
256	  const [focused, setFocused] = useState<string | null>(null);
257	  const [dock, setDock] = useState<"panel" | "outline" | "away">("panel");
258	  const [onlyColumn, setOnlyColumn] = useState<{
259	    layer: number;
260	    claims: readonly string[];
261	  } | null>(null);
262	  const [overlay, setOverlay] = useState<"palette" | "sheet" | null>(null);
263	  const [intervening, setIntervening] = useState(false);
264	  const [naming, setNaming] = useState(false);
265	  const [status, setStatus] = useState(
266	    "Press ? for every key. j and k walk a column; h and l follow the wires.",
267	  );
268	  const [announcement, setAnnouncement] = useState("");
269	  const [arriving, setArriving] = useState(true);
270	  const lastBranch = useRef<string | null>(null);
271	
272	  const open = shop.branches.find((branch) => branch.id === shop.openId);
273	  const paintings = useMemo(
274	    () => (open === undefined ? null : bothPaintings(base, open)),
275	    [base, open],
276	  );
277	  const world = paintings === null ? base : showing === "now" ? paintings.now : paintings.before;
278	
279	  /**
280	   * One box per claim, tall enough for whichever of the two paintings needs more
281	   * room — a claim grows badges when an edit touched it. Reserving the taller box
282	   * is what lets the union be laid out once and painted twice with nothing
283	   * moving.
284	   */
285	  const heights = useMemo(() => {
286	    if (paintings === null) {
287	      return undefined;
288	    }
289	    const reserved = new Map<string, number>();
290	    for (const side of [paintings.now, paintings.before]) {
291	      for (const claim of side.claims) {
292	        reserved.set(claim.id, Math.max(reserved.get(claim.id) ?? 0, tileHeight(claim)));
293	      }
294	    }
295	    return reserved;
296	  }, [paintings]);
297	
298	  const rows = useMemo(() => (paintings === null ? [] : endings(paintings.now)), [paintings]);
299	  const outline = useMemo(() => outlineOf(world), [world]);
300	
301	  // A branch has just been opened or made. Three things follow, in this order:
302	  // the map says out loud what the branch did, the wires arrive again in causal
303	  // order, and — because creating a claim moves focus to it — the keyboard lands
304	  // on the claim the branch added, so the view frames the thing you just made
305	  // rather than leaving you to hunt for it.
306	  useEffect(() => {
307	    if (shop.openId === lastBranch.current) {
308	      return;
309	    }
310	    lastBranch.current = shop.openId;
311	    setShowing("now");
312	    setArriving(true);
313	    const settles = window.setTimeout(() => setArriving(false), WAVE_SETTLES_AFTER);
314	    if (paintings === null) {
315	      setAnnouncement("");
316	      return () => window.clearTimeout(settles);
317	    }
318	    setAnnouncement(branchAnnouncement(paintings.now));
319	    const arrived = paintings.now.claims.find((claim) => claim.diff === "added");
320	    if (arrived !== undefined) {
321	      setFocused(arrived.id);
322	      setSelection({ kind: "claim", id: arrived.id });
323	      setStatus(`your edit added this claim · ${arrived.claim}`);
324	    }
325	    return () => window.clearTimeout(settles);
326	  }, [shop.openId, paintings]);
327	
328	  const edit = useCallback((made: Edit) => {
329	    setShop((was) =>
330	      appendEdit(was.openId === null ? forkBranch(was, "Your own branch") : was, made),
331	    );
332	  }, []);
333	
334	  const keys: MapKeys = useMemo(
335	    () => ({
336	      intervene: () => {
337	        setDock("panel");
338	        setIntervening(true);
339	      },
340	      branch: () => {
341	        setDock("panel");
342	        setNaming(true);
343	      },
344	      flipWorlds: () => {
345	        if (paintings === null) {
346	          setStatus("there is nothing to flip to — no branch is open");
347	          return;
348	        }
349	        setShowing((was) => {
350	          const next = was === "now" ? "before" : "now";
351	          setStatus(
352	            next === "now"
353	              ? "the map with your edits"
354	              : "the map as it was written, with what your branch adds drawn faint",
355	          );
356	          return next;
357	        });
358	      },
359	      outline: () =>
360	        setDock((was) => {
361	          setOnlyColumn(null);
362	          return was === "outline" ? "panel" : "outline";
363	        }),
364	      panel: () => setDock((was) => (was === "away" ? "panel" : "away")),
365	      palette: () => setOverlay("palette"),
366	    }),
367	    [paintings],
368	  );
369	
370	  // ⌘K, ? and Escape work wherever you are on the screen, not only on the map,
371	  // because two of them are how you find out what the others do.
372	  useEffect(() => {
373	    const onKey = (event: KeyboardEvent): void => {
374	      const target = event.target as HTMLElement | null;
375	      const typing =
376	        target?.tagName === "INPUT" ||
377	        target?.tagName === "TEXTAREA" ||
378	        target?.isContentEditable === true;
379	      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
380	        event.preventDefault();
381	        setOverlay((was) => (was === "palette" ? null : "palette"));
382	        return;
383	      }
384	      if (event.key === "Escape") {
385	        setOverlay(null);
386	        setIntervening(false);
387	        setNaming(false);
388	        return;
389	      }
390	      if (event.key === "?" && !typing) {
391	        event.preventDefault();
392	        setOverlay((was) => (was === "sheet" ? null : "sheet"));
393	      }
394	    };
395	    window.addEventListener("keydown", onKey);
396	    return () => window.removeEventListener("keydown", onKey);
397	  }, []);
398	
399	  const commands: Command[] = useMemo(() => {
400	    const made: Command[] = [
401	      {
402	        name: "The map as it was written",
403	        does: "Close the branch. Also the first row of the branch panel.",
404	        run: () => setShop((was) => openBranch(was, null)),
405	      },
406	      ...shop.branches.map((branch) => ({
407	        name: `Open the branch: ${branch.label}`,
408	        does: `${branch.edits.length} edits. Also a row in the branch panel.`,
409	        run: () => setShop((was) => openBranch(was, branch.id)),
410	      })),
411	      {
412	        name: "Flip between the two maps",
413	        does: "The same as pressing Space on the map. A hard switch, never a fade.",
414	        run: keys.flipWorlds,
415	      },
416	      {
417	        name: "Change this claim",
418	        does: "The six things you can do to it. The same as pressing E on the map.",
419	        run: keys.intervene,
420	      },
421	      {
422	        name: "Start a branch",
423	        does: "The same as pressing B on the map, and as the button in the branch panel.",
424	        run: keys.branch,
425	      },
426	      {
427	        name: "Read the map as a list",
428	        does: "The same as pressing O. Every claim, one sentence each.",
429	        run: () => {
430	          setOnlyColumn(null);
431	          setDock("outline");
432	        },
433	      },
434	      {
435	        name: "Show or hide the panel beside the map",
436	        does: "The same as pressing P, when you want the whole width for the map.",
437	        run: keys.panel,
438	      },
439	      {
440	        name: "Every key, on one sheet",
441	        does: "The same as pressing the question mark.",
442	        run: () => setOverlay("sheet"),
443	      },
444	      {
445	        name: "Back to the launchpad",
446	        does: "The same as the link at the top left.",
447	        run: onLeave,
448	      },
449	    ];
450	    return made;
451	  }, [shop.branches, keys, onLeave]);
452	
453	  const pick = useCallback((id: string) => {
454	    setFocused(id);
455	    setSelection({ kind: "claim", id });
456	  }, []);
457	
458	  return (
459	    <main className="page page--map">
460	      <header className="map-bar">
461	        <button className="map-bar__back" type="button" onClick={onLeave}>
462	          <span aria-hidden="true">←</span> Back to the launchpad
463	        </button>
464	        <h1 className="map-bar__title">{base.title}</h1>
465	        {open === undefined ? (
466	          <p className="map-bar__where">The map as it was written</p>
467	        ) : (
468	          <p className="map-bar__where">
469	            {/* A branch's hue rides on its name chip and its lane and nowhere
470	                else, and the chip always carries the branch's name — so which
471	                branch you are in is readable with no colour at all. */}
472	            <span className="map-bar__chip" data-hue={open.hue} aria-hidden="true" />
473	            {open.label}
474	            <span className="map-bar__side">
475	              {showing === "now" ? "with your edits" : "as it was written"}
476	            </span>
477	          </p>
478	        )}
479	        <button className="map-bar__sheet" type="button" onClick={() => setOverlay("sheet")}>
480	          Every key (?)
481	        </button>
482	      </header>
483	
484	      {/* The map and the panel, side by side. The panel is part of the screen
485	          rather than something that appears over it: there are no pop-ups
486	          anywhere in this product, and a dialog you have to dismiss would steal
487	          the map that makes the detail mean anything. */}
488	      <div className="map-body">
489	        <div className="map-stage">
490	          <MapCanvas
491	            world={world}
492	            selection={selection}
493	            onSelect={setSelection}
494	            focused={focused}
495	            onFocused={setFocused}
496	            heights={heights}
497	            mapKey={`${base.baseId}:${shop.openId ?? "as-written"}`}
498	            keys={keys}
499	            onStatus={setStatus}
500	            onOverflow={(column) => {
501	              setOnlyColumn(column);
502	              setDock("outline");
503	            }}
504	            arriving={arriving}
505	          />
506	          {overlay === "palette" ? (
507	            <CommandPalette open={true} onClose={() => setOverlay(null)} commands={commands} />
508	          ) : null}
509	          {overlay === "sheet" ? (
510	            <ShortcutsSheet open={true} onClose={() => setOverlay(null)} />
511	          ) : null}
512	          <p className="map-status">
513	            <span className="map-status__mark">last key</span>
514	            {status}
515	          </p>
516	        </div>
517	
518	        {dock === "away" ? null : (
519	          <aside className="dock" aria-label="The panel beside the map">
520	            {dock === "outline" ? (
521	              <Outline
522	                items={outline}
523	                onPick={pick}
524	                focused={focused}
525	                {...(onlyColumn === null
526	                  ? {}
527	                  : {
528	                      only: new Set(onlyColumn.claims),
529	                      filter:
530	                        `Only the claims in column ${onlyColumn.layer}, which is what the ` +
531	                        `collapsed tile on the map stands for. Press O for all of them.`,
532	                    })}
533	              />
534	            ) : (
535	              <>
536	                {intervening ? (
537	                  <InterventionPanel
538	                    world={world}
539	                    selection={selection}
540	                    onEdit={edit}
541	                    onClose={() => setIntervening(false)}
542	                  />
543	                ) : null}
544	                <BranchPanel
545	                  branches={shop.branches}
546	                  openId={shop.openId}
547	                  world={world}
548	                  onOpen={(id) => setShop((was) => openBranch(was, id))}
549	                  onFork={(label) => setShop((was) => forkBranch(was, label))}
550	                  naming={naming}
551	                  onNaming={setNaming}
552	                />
553	                {open === undefined ? null : (
554	                  <DeltaRail rows={rows} ranked={false} summary={NO_SUMMARY_YET} />
555	                )}
556	                <Inspector world={world} selection={selection} />
557	              </>
558	            )}
559	          </aside>
560	        )}
561	      </div>
562	
563	      {/* What a branch did, said out loud for a reader who is not looking at the
564	          picture. Polite: it waits for a pause rather than cutting across
565	          whatever is being read. */}
566	      <p className="map-live" aria-live="polite">
567	        {announcement}
568	      </p>
569	      <p className="map-origin">{world.origin}</p>
570	    </main>
571	  );
572	}
573	
574	/**
575	 * Where maps come from.
576	 *
577	 * Today this reads the stored example the server ships with. When the engine's
578	 * world route lands, this one line becomes `new ApiWorldSource()` and every
579	 * number slot that reads as an absence today fills in. Nothing else on this
580	 * screen changes, which is the whole reason there is a seam here at all.
581	 */
582	const DEFAULT_SOURCE: WorldSource = new FixtureWorldSource();
583	
584	/** What the screen needs. Both have defaults; both exist so they can be swapped. */
585	export interface AppProps {
586	  /** Where maps and worlds come from. */
587	  readonly source?: WorldSource;
588	  /** How the list of stored examples is read. */
589	  readonly listExamples?: () => Promise<FixtureSummary[]>;
590	}
591	
592	/** The screen. */
593	export function App({ source = DEFAULT_SOURCE, listExamples = readExampleList }: AppProps = {}) {
594	  const health = useAnswer(readHealth);
595	  const readiness = useAnswer(readReadiness);
596	  const about = useAnswer(readAbout);
597	  const examples = useAnswer(listExamples);
598	
599	  const [screen, setScreen] = useState<Screen>({ at: "launchpad" });
600	
601	  const open = useCallback(
602	    (id: string) => {
603	      setScreen({ at: "opening", id });
604	      // The world and the map's own branches, together: the world is what gets
605	      // drawn, and the branches are the edits somebody already made to it, which
606	      // the panel lists and the diff view folds on. Both come from the same
607	      // stored example through the same seam.
608	      Promise.all([source.readWorld({ baseId: id }), source.readBundle(id)]).then(
609	        ([world, bundle]) => setScreen({ at: "map", world, branches: branchesOf(bundle) }),
610	        (reason: unknown) => setScreen({ at: "failed", id, reason: inWords(reason) }),
611	      );
612	    },
613	    [source],
614	  );
615	
616	  const toLaunchpad = useCallback(() => setScreen({ at: "launchpad" }), []);
617	
618	  const readings = useMemo(
619	    () => [serverReading(health), modelKeyReading(readiness), versionReading(about)],
620	    [health, readiness, about],
621	  );
622	
623	  if (screen.at === "map") {
624	    return <MapScreen base={screen.world} branches={screen.branches} onLeave={toLaunchpad} />;
625	  }
626	
627	  if (screen.at !== "launchpad") {
628	    return (
629	      <main className="page page--map">
630	        <header className="map-bar">
631	          <button className="map-bar__back" type="button" onClick={toLaunchpad}>
632	            <span aria-hidden="true">←</span> Back to the launchpad
633	          </button>
634	          <h1 className="map-bar__title">Strait of Hormuz</h1>
635	        </header>
636	
637	        <div className="map-waiting">
638	          <p className="map-waiting__line">
639	            {screen.at === "opening"
640	              ? `Reading the stored map from /api/fixtures/${screen.id}.`
641	              : screen.reason}
642	          </p>
643	        </div>
644	      </main>
645	    );
646	  }
647	
648	  return (
649	    <main className="page">
650	      <div className="column">
651	        <header className="masthead">
652	          <h1 className="wordmark">Katalyst</h1>
653	          <p className="purpose">
654	            Type an event you think will happen. See what it would cause, step by step, ending in
655	            trades.
656	          </p>
657	        </header>
658	
659	        <Launchpad
660	          examples={examples.state === "answered" ? examples.value : null}
661	          failure={examples.state === "failed" ? examples.reason : null}
662	          notLiveReason={notLiveReason(readiness)}
663	          onOpen={open}
664	        />
665	
666	        <section aria-labelledby="status-heading">
667	          <h2 className="section-heading" id="status-heading">
668	            What this build can do right now
669	          </h2>
670	          <dl className="status-strip">
671	            {readings.map((reading) => (
672	              <StatusRow key={reading.label} reading={reading} />
673	            ))}
674	          </dl>
675	          <p className="provenance">
676	            Every reading above came from the server, at <code>/api/healthz</code>,{" "}
677	            <code>/api/readyz</code> and <code>/api/about</code>. The examples came from{" "}
678	            <code>/api/fixtures</code>. Nothing on this screen is written into the page.
679	          </p>
680	        </section>
681	      </div>
682	    </main>
683	  );
684	}
