89	 * @param claimIds Every claim on the union of the two maps — the base map's
90	 *   claims and any the branch adds — in the order the map serves them.
91	 * @param arrows Every arrow on the union of the two maps. Feedback arrows are
92	 *   set aside inside this function, because it is being asked what an edit can
93	 *   move.
94	 * @param edits The branch's edits, in the order they were made.
95	 */
96	export function readDiff(
97	  claimIds: readonly string[],
98	  arrows: readonly Arrow[],
99	  edits: readonly Edit[],
100	): DiffReading {
101	  // The map as it stands while the edits are applied, one after another. It
102	  // starts as the base map with feedback arrows set aside, loses the arrows a
103	  // supposition cuts, and gains the arrows an addition brings.
104	  let working = forward(arrows.filter((arrow) => !isAddedByAnEdit(arrow.id, edits)));
105	
106	  const affected = new Set<string>();
107	  const canMove = new Set<string>();
108	  const added = new Set<string>();
109	  const killed = new Set<string>();
110	  const addedLinks = new Set<string>();
111	  const cutLinks = new Set<string>();
112	  const retunedLinks = new Set<string>();
113	
114	  /** Everything this claim reaches, itself included. */
115	  const fromHere = (claim: string): Set<string> => {
116	    const reached = descendants(claim, working);
117	    reached.add(claim);
118	    return reached;
119	  };
120	
121	  for (const edit of edits) {
122	    switch (edit.op) {
123	      case "do": {
124	        // "Take this as given, and do not tell me what caused it": the arrows
125	        // into the target that exist right now are cut. An arrow added later is
126	        // live, which is what lets a later edit push a supposed claim back down.
127	        for (const arrow of working) {
128	          if (arrow.target === edit.target) {
129	            cutLinks.add(arrow.id);
130	          }
131	        }
132	        working = working.filter((arrow) => arrow.target !== edit.target);
133	        const reached = fromHere(edit.target);
134	        addAll(affected, reached);
135	        addAll(canMove, reached);
136	        if (!edit.value) {
137	          killed.add(edit.target);
138	        }
139	        break;
140	      }
141	      case "observe": {
142	        // "This is news": nothing is cut, so what is learned travels back up the
143	        // arrows into the causes and out again along everything they lead to.
144	        const reached = fromHere(edit.target);
145	        for (const cause of ancestors(edit.target, working)) {
146	          addAll(reached, fromHere(cause));
147	        }
148	        addAll(affected, reached);
149	        addAll(canMove, reached);
150	        break;
151	      }
152	      case "insert": {
153	        // The claim and its arrows arrive together, so the map is never left
154	        // holding a claim that causes nothing.
155	        for (const arrow of edit.arrows) {
156	          addedLinks.add(arrow.id);
157	          working.push({ ...arrow, reflexive: false });
158	        }
159	        added.add(edit.claimId);
160	        const reached = fromHere(edit.claimId);
161	        addAll(affected, reached);
162	        addAll(canMove, reached);
163	        break;
164	      }
