169	        retunedLinks.add(edit.link);
170	        if (arrow !== undefined) {
171	          const reached = fromHere(arrow.target);
172	          addAll(affected, reached);
173	          addAll(canMove, reached);
174	        }
175	        break;
176	      }
177	      case "refine":
