/**
 * What your edit did to the map, worked out from the branch and nothing else.
 *
 * Two maps exist the moment you make an edit, and one question matters: **what
 * did my edit reach, and what did it provably leave alone?** This file answers
 * it. It reads the base map and the list of edits, and hands back one word per
 * claim. **No arithmetic anywhere**: no strength is added, no likelihood is
 * moved, no shape is evaluated. Following arrows is walking, not calculating —
 * see `reach.ts` for the one rule about which arrows count.
 *
 * The four words, and where each comes from:
 *
 * | Word | Worked out by |
 * |---|---|
 * | `added` | The claim arrives in an **Add a claim** edit |
 * | `killed` | The claim is the target of a **Suppose this is false** — full stop |
 * | `downstream` | The claim is in the affected set of at least one edit |
 * | `untouched` | Everything else, and the map can say so without hedging |
 *
 * The fifth word, `shifted`, needs two numbers to compare. Nothing here ever
 * produces one, and the check for that is a test: a diff over worlds whose
 * likelihoods are absent never shifts anything.
 *
 * **Edits are applied in order, to a map that changes as they go.** That is not
 * a nicety; it is the whole of the stored example's showcase. *Suppose the
 * strait reopens* cuts the arrows into that claim **that exist at that moment** —
 * none, because it is the hypothesis. The next edit hangs a new arrow onto it,
 * and an arrow added afterwards is live. So the strike can push the strait's
 * opening back down even though the reader supposed it, and the reason is
 * visible as a sequence of three edits rather than as a number that moved on its
 * own.
 *
 * **Which claims each operation reaches** is settled once, in
 * `spec/multiverse/interventions.md`'s affected-set table, and copied here:
 *
 * | Operation | Reaches |
 * |---|---|
 * | **Suppose this is true / false** | The target and everything it causes |
 * | **This happened** | The target, what it causes, what causes it, and what those cause |
 * | **Add a claim** | The new claim and everything it causes |
 * | **Change this push** | The claim at the arrow's head, and everything that claim causes |
 * | **Split this claim** | The target's own internals — not built |
 * | **My own number** | One slot on one claim: your own number on the target |
 */

import type { DiffState, Edit } from "../../world/types";
import { type Arrow, ancestors, descendants, forward } from "./reach";

/** What reading a branch against its base map tells you. */
export interface DiffReading {
  /** One word per claim: what the edits did to it. */
  readonly states: ReadonlyMap<string, DiffState>;
  /**
   * The claims whose **computed** numbers an edit can move.
   *
   * Nearly the same set as the `downstream` claims, and deliberately not
   * identical: **My own number** reaches a claim — it writes your number into
   * your own slot on it — but it is not pushed through the map, so the model's
   * number on that claim has not moved and must not be blanked out. This set is
   * what decides whether a claim's model number reads its absence.
   */
  readonly canMove: ReadonlySet<string>;
  /** Arrows an **Add a claim** edit brought with it. */
  readonly addedLinks: ReadonlySet<string>;
  /**
   * Arrows a **Suppose this is true** or **Suppose this is false** cut.
   *
   * Supposing a claim cuts the arrows into it that exist at that moment: you are
   * saying "take this as given, and do not tell me what caused it". A cut arrow
   * is still drawn — faint and dashed, the same way the other world is drawn —
   * because an arrow that vanished would be a change nobody could see.
   */
  readonly cutLinks: ReadonlySet<string>;
  /** Arrows a **Change this push** edit moved. */
  readonly retunedLinks: ReadonlySet<string>;
}

/** Add everything in one set to another. */
function addAll(into: Set<string>, from: Iterable<string>): void {
  for (const one of from) {
    into.add(one);
  }
}

/**
 * Read a branch against its base map: one word per claim, and what happened to
 * the arrows.
 *
 * @param claimIds Every claim on the union of the two maps — the base map's
 *   claims and any the branch adds — in the order the map serves them.
 * @param arrows Every arrow on the union of the two maps. Feedback arrows are
 *   set aside inside this function, because it is being asked what an edit can
 *   move.
 * @param edits The branch's edits, in the order they were made.
 */
export function readDiff(
  claimIds: readonly string[],
  arrows: readonly Arrow[],
  edits: readonly Edit[],
): DiffReading {
  // The map as it stands while the edits are applied, one after another. It
  // starts as the base map with feedback arrows set aside, loses the arrows a
  // supposition cuts, and gains the arrows an addition brings.
  let working = forward(arrows.filter((arrow) => !isAddedByAnEdit(arrow.id, edits)));

  const affected = new Set<string>();
  const canMove = new Set<string>();
  const added = new Set<string>();
  const killed = new Set<string>();
  const addedLinks = new Set<string>();
  const cutLinks = new Set<string>();
  const retunedLinks = new Set<string>();

  /** Everything this claim reaches, itself included. */
  const fromHere = (claim: string): Set<string> => {
    const reached = descendants(claim, working);
    reached.add(claim);
    return reached;
  };

  for (const edit of edits) {
    switch (edit.op) {
      case "do": {
        // "Take this as given, and do not tell me what caused it": the arrows
        // into the target that exist right now are cut. An arrow added later is
        // live, which is what lets a later edit push a supposed claim back down.
        for (const arrow of working) {
          if (arrow.target === edit.target) {
            cutLinks.add(arrow.id);
          }
        }
        working = working.filter((arrow) => arrow.target !== edit.target);
        const reached = fromHere(edit.target);
        addAll(affected, reached);
        addAll(canMove, reached);
        if (!edit.value) {
          killed.add(edit.target);
        }
        break;
      }
      case "observe": {
        // "This is news": nothing is cut, so what is learned travels back up the
        // arrows into the causes and out again along everything they lead to.
        const reached = fromHere(edit.target);
        for (const cause of ancestors(edit.target, working)) {
          addAll(reached, fromHere(cause));
        }
        addAll(affected, reached);
        addAll(canMove, reached);
        break;
      }
      case "insert": {
        // The claim and its arrows arrive together, so the map is never left
        // holding a claim that causes nothing.
        for (const arrow of edit.arrows) {
          addedLinks.add(arrow.id);
          working.push({ ...arrow, reflexive: false });
        }
        added.add(edit.claimId);
        const reached = fromHere(edit.claimId);
        addAll(affected, reached);
        addAll(canMove, reached);
        break;
      }
      case "retune": {
        // One number on one arrow. The earliest thing that can move is the claim
        // that arrow points at.
        const arrow = working.find((one) => one.id === edit.link);
        retunedLinks.add(edit.link);
        if (arrow !== undefined) {
          const reached = fromHere(arrow.target);
          addAll(affected, reached);
          addAll(canMove, reached);
        }
        break;
      }
      case "refine":
        // Splitting a claim into finer ones is not built. The edit is recorded
        // in the branch, and the panel says plainly that it is not live, so that
        // nothing here quietly claims a reach it does not have.
        break;
      case "believe":
        // Your own number sits beside the model's and the market's and is never
        // averaged with either. It is not pushed through the map, so it reaches
        // this claim and moves nothing the map computes.
        affected.add(edit.target);
        break;
    }
  }

  const states = new Map<string, DiffState>();
  for (const id of claimIds) {
    states.set(
      id,
      killed.has(id)
        ? "killed"
        : added.has(id)
          ? "added"
          : affected.has(id)
            ? "downstream"
            : "untouched",
    );
  }

  return { states, canMove, addedLinks, cutLinks, retunedLinks };
}

/** True when this arrow is one an **Add a claim** edit brings, rather than one the base map had. */
function isAddedByAnEdit(id: string, edits: readonly Edit[]): boolean {
  return edits.some((edit) => edit.op === "insert" && edit.arrows.some((arrow) => arrow.id === id));
}

/**
 * The second world: the base map with a branch folded onto it, as far as
 * structure goes and not one step further.
 *
 * **What this builds is real, and what it leaves out is left out on purpose.**
 * Applying a branch properly means running the map's numbers again, and that is
 * the engine's work. This half of the product does none of it. So the world
 * below carries everything the branch says about *shape* — which claim arrived,
 * which arrows came with it, which arrows a supposition cut, which claims the
 * edit can reach and which it provably cannot — and, wherever a likelihood would
 * have moved, **an absence with its reason** rather than the old number left
 * lying there looking current.
 *
 * That is the honest half and it is the useful half: *here is what your edit can
 * reach, and here is what it cannot* is this product's central correctness claim
 * made visible, and it needs no arithmetic at all.
 *
 * Three rules hold it together:
 *
 * 1. **A claim your edit can reach shows its model number's absence.** The
 *    number on the base map is the base map's number; on this branch it would be
 *    something else, and nothing has worked out what. Leaving the old one on
 *    screen would be the quietest lie in the product.
 * 2. **A claim your edit provably cannot reach keeps its number, unhedged.**
 *    That is not optimism: an edit reaches only what is still joined to its
 *    subject, and everything else is identical.
 * 3. **Your own number is yours.** *My own number* writes into your own slot and
 *    is never averaged with the model's or a market's, and it is not pushed
 *    through the map — so it fills in immediately and moves nothing else.
 */

import type { Absence, BranchView, ClaimView, LinkView, Slot, WorldView } from "../../world/types";
import { badgesByClaim, standingByClaim } from "./badges";
import { readDiff } from "./diffState";
import type { Arrow } from "./reach";

/**
 * What stands where a likelihood would go on a claim this edit can reach.
 *
 * The words are the shared vocabulary's; the sentence says which number is
 * missing and who would have to work it out.
 */
export const NO_ENGINE: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "Nothing has worked this number through the map yet. Your edit can reach this claim, so " +
    "its likelihood would move — and the part of this product that works out where to is not " +
    "connected. The old number would be the base map's, not this branch's.",
};

/** That slot, ready to be dropped into a claim. */
const NO_ENGINE_SLOT: Slot = { absence: NO_ENGINE };

/**
 * The two paintings of one diff: the map with your edits, and the map as it was.
 *
 * **One layout, two paintings.** Both worlds hold exactly the same claims and the
 * same arrows, in the same order — so the union is laid out once and nothing
 * moves when you flip between them. What differs is what each tile *says*: in
 * the map as it was, the strike is a ghost and every number is the one the map
 * was written with; in the map with your edits, the strike is a real tile with
 * an accent ring and every number your edit could move reads its absence.
 *
 * A claim or an arrow that only one of the two has is drawn in the other as a
 * **ghost** — faint, in the same place — rather than vanishing. A tile that
 * disappeared would be a change you could only catch by remembering where it had
 * been.
 *
 * @param base The base world, exactly as the map was written.
 * @param branch The branch to fold onto it.
 */
export function bothPaintings(
  base: WorldView,
  branch: BranchView,
): { now: WorldView; before: WorldView } {
  const now = branchWorld(base, branch);
  const added = new Set(branch.claims.map((claim) => claim.id));
  const addedArrows = new Set(branch.links.map((link) => link.id));
  return {
    now: {
      ...now,
      // An arrow a supposition cut is not in the map with your edits: supposing a
      // claim says "do not tell me what caused it". It is still drawn, faint, in
      // the place it was.
      links: now.links.map((link) => ({ ...link, ghost: link.change === "cut" })),
    },
    before: {
      ...base,
      claims: [
        ...base.claims,
        ...branch.claims.map((claim) => ({ ...claim, ghost: true, diff: "added" as const })),
      ],
      links: [
        ...base.links,
        ...branch.links.map((link) => ({ ...link, ghost: true, change: "added" as const })),
      ],
      origin:
        `${base.origin} This is the map as it was written, with the ` +
        `${addedArrows.size === 1 ? "one arrow" : `${addedArrows.size} arrows`} and the ` +
        `${added.size === 1 ? "claim" : "claims"} your branch adds drawn faint, in the places ` +
        `they take on the other side of the switch — so that flipping between the two moves ` +
        `nothing.`,
    },
  };
}

/** Every arrow, as working out what an edit reaches needs it. */
function asArrows(links: readonly LinkView[]): Arrow[] {
  return links.map((link) => ({
    id: link.id,
    source: link.source,
    target: link.target,
    reflexive: link.reflexive,
  }));
}

/**
 * Fold a branch onto a base world and hand back the second world.
 *
 * Both worlds are drawn in one coordinate space afterwards, so nothing here
 * moves a claim: the union of the two maps is laid out once and painted twice.
 *
 * @param base The base world, exactly as the map was written.
 * @param branch The branch: its edits in order, and whatever whole claims and
 *   arrows the map supplied for them.
 */
export function branchWorld(base: WorldView, branch: BranchView): WorldView {
  const claims = [...base.claims, ...branch.claims];
  const links = [...base.links, ...branch.links];
  const diff = readDiff(
    claims.map((claim) => claim.id),
    asArrows(links),
    branch.edits,
  );

  const words = new Map(claims.map((claim) => [claim.id, claim.claim]));
  for (const edit of branch.edits) {
    if (edit.op === "insert" && !words.has(edit.claimId)) {
      words.set(edit.claimId, edit.words);
    }
  }
  const badges = badgesByClaim(branch.edits, {
    words,
    arrows: new Map(
      branch.links.map((link) => [
        link.id,
        { source: link.source, mode: link.mode, strength: link.strength },
      ]),
    ),
  });
  const standing = standingByClaim(branch.edits, badges);

  // Your own numbers, from every **My own number** edit on this branch. A later
  // one on the same claim replaces an earlier one on screen; both stay in the
  // branch, in order, because the branch is the audit trail.
  const yours = new Map(
    branch.edits.flatMap((edit) => (edit.op === "believe" ? [[edit.target, edit.belief]] : [])),
  );

  return {
    ...base,
    branch,
    claims: claims.map((claim): ClaimView => {
      const ownNumber = yours.get(claim.id);
      return {
        ...claim,
        diff: diff.states.get(claim.id) ?? "untouched",
        badges: badges.get(claim.id) ?? [],
        standing: standing.get(claim.id),
        beliefs: {
          ...claim.beliefs,
          model: diff.canMove.has(claim.id) ? NO_ENGINE_SLOT : claim.beliefs.model,
          user: ownNumber === undefined ? claim.beliefs.user : { reading: ownNumber },
        },
        // A whole chain's likelihood is multiplied out where the map's numbers
        // are worked out, and never here. It was an absence on the base world
        // and it is the same absence on this one.
        pathProduct: claim.pathProduct,
      };
    }),
    links: links.map(
      (link): LinkView => ({
        ...link,
        change: diff.addedLinks.has(link.id)
          ? "added"
          : diff.cutLinks.has(link.id)
            ? "cut"
            : diff.retunedLinks.has(link.id)
              ? "retuned"
              : undefined,
      }),
    ),
    origin:
      `${base.origin} This branch — "${branch.label}" — is the same map with ` +
      `${branch.edits.length === 1 ? "one edit" : `${branch.edits.length} edits`} folded onto ` +
      `it. What you can see of it is shape: which claim arrived, which arrows came with it, and ` +
      `which claims those arrows can reach. Every likelihood a branch would move reads "no ` +
      `engine yet", because nothing has worked one out.`,
  };
}

/**
 * The endings your edit can reach, in the order the map stores them.
 *
 * An **ending** is a claim the chain stops at: one that names an instrument you
 * could trade, or one that names why there is nothing to trade. They are what
 * the rail beside the map lists, because they are where an argument turns into a
 * position.
 *
 * **This build does not rank them and does not compute anything.** With the
 * engine, the rail is the endings whose numbers moved, in the order the engine
 * put them in — biggest move along the best-backed route first. Before the
 * engine there is no such order, and inventing one would be inventing the single
 * thing the rail exists to tell you. So the order is **map order**, which is
 * visibly arbitrary and says so on screen, and where each number will go there is
 * an absence with its reason.
 *
 * The two columns beside the change are never folded into any ordering, before
 * the engine or after it:
 *
 * | On screen | The question it answers |
 * |---|---|
 * | **how firm** | How firm is this number? The width of this world's own range on the claim — the same quantity the tile shows, so the rail and the tile cannot disagree |
 * | **same direction** | Did it point the same way whatever numbers we started from? The share of the two thousand versions of the map that moved the same way |
 *
 * They answer different questions and a trader weighs them separately, which is
 * why they are columns and not one score. Folding the width into a rank would
 * sink exactly the claims that most deserve a second look.
 */

import type { Absence, DeltaRow, Known, WorldView } from "../../world/types";

/** Where the change itself will go. */
const NO_CHANGE_YET: Absence = {
  kind: "no_engine",
  words: "no engine yet",
  reason:
    "Nothing has worked this ending's number through the map, so there is no before and no " +
    "after to show.",
};

/** Where **how firm** will go. */
const NO_WIDTH_YET: Absence = {
  kind: "no_engine",
  words: "—",
  reason:
    "How firm a number is, is the width of this world's own range on the claim — the same " +
    "range the tile shows. There is no number yet, so there is no range around it.",
};

/** Where **same direction** will go. */
const NO_AGREEMENT_YET: Absence = {
  kind: "no_engine",
  words: "—",
  reason:
    "Whether an ending points the same way whatever numbers we started from is read across two " +
    "thousand versions of the map — each one a coherent set of numbers this model would have " +
    "stood behind. Nothing has run one yet.",
};

/** Where the one-line summary of the whole edit will go. */
export const NO_SUMMARY_YET: Known<string> = {
  absence: {
    kind: "no_engine",
    words: "no engine yet",
    reason:
      "The one line saying what this edit did to the trades is written from the numbers it " +
      "moved, and nothing has moved one. What the map can say without them is underneath: which " +
      "claim arrived, which claims your edit can reach, and which it provably cannot.",
  },
};

/**
 * The endings this branch can reach, in map order.
 *
 * @param world A world with a branch folded onto it. On the base world nothing
 *   has been edited, so nothing is reachable and the list is empty.
 * @returns One row per reachable ending, each with its absences.
 */
export function endings(world: WorldView): DeltaRow[] {
  return world.claims
    .filter(
      (claim) =>
        (claim.kind === "market" || claim.kind === "not_tradeable") &&
        claim.diff !== undefined &&
        claim.diff !== "untouched",
    )
    .map(
      (claim): DeltaRow => ({
        claimId: claim.id,
        label: claim.claim,
        kind: claim.kind,
        move: { absence: NO_CHANGE_YET },
        rangeWidth: { absence: NO_WIDTH_YET },
        agreement: { absence: NO_AGREEMENT_YET },
      }),
    );
}

