85	/** The badge a claim the reader added earns. */
86	const ADDED: Badge = {
87	  words: "Added",
88	  reason: "This claim, and the arrows that attach it, arrived as one edit on this branch.",
89	};
90	
91	/**
92	 * Work out every badge on every claim, in the order the edits were made.
93	 *
94	 * @param edits The branch's edits, in order.
95	 * @param context The claims' words and the arrows the edits brought.
96	 * @returns One list of badges per claim that has any, in order.
97	 */
98	export function badgesByClaim(edits: readonly Edit[], context: BadgeContext): Map<string, Badge[]> {
99	  const badges = new Map<string, Badge[]>();
100	  const add = (claim: string, badge: Badge): void => {
101	    badges.set(claim, [...(badges.get(claim) ?? []), badge]);
102	  };
