104	  // Which claims are under a supposition that still holds, and which arrows
105	  // could undermine one. An arrow only counts if it was added *after* the
106	  // supposition — supposing a claim cuts the arrows into it that exist at that
107	  // moment — and only if it is the holding-up kind pushing against the claim:
108	  // an arrow that fires once and fades cannot take back a supposition, because a
109	  // toppled domino stays toppled.
110	  const supposedNow = new Map<string, { at: string; index: number }>();
111	  const undermining = new Map<string, { source: string; from: number }[]>();
112	
113	  edits.forEach((edit, index) => {
114	    switch (edit.op) {
115	      case "do":
116	        add(edit.target, supposed(edit.at, edit.value));
117	        if (edit.value) {
118	          supposedNow.set(edit.target, { at: edit.at, index });
119	        } else {
120	          supposedNow.delete(edit.target);
121	        }
122	        // A supposition cuts every arrow into its target that exists now, so
123	        // anything recorded as undermining it is gone.
124	        undermining.delete(edit.target);
125	        if (edit.value) {
126	          retractIfUndermined(edit.target, edit.at);
127	        }
128	        break;
129	      case "observe":
130	        add(edit.target, happened(edit.at));
131	        if (edit.value) {
