138	          const whole = context.arrows.get(arrow.id);
139	          if (whole === undefined || whole.mode !== "sustain" || whole.strength >= 0) {
140	            continue;
141	          }
142	          undermining.set(arrow.target, [
143	            ...(undermining.get(arrow.target) ?? []),
144	            { source: whole.source, from: index },
145	          ]);
146	        }
147	        break;
148	      case "retune":
149	      case "refine":
150	      case "believe":
151	        // **Change this push** and **Split this claim** are about an arrow and a
152	        // claim's internals rather than about a claim's standing, and the panel
153	        // lists them with their badges. **My own number** earns no badge at all:
154	        // the three-up belief chip is the badge.
155	        break;
156	    }
157	  });
158	
159	  /**
160	   * If making this claim true undermines a supposition somewhere, say so on the
161	   * claim that was supposed.
162	   */
163	  function retractIfUndermined(nowTrue: string, at: string): void {
164	    for (const [claim, arrows] of undermining) {
