1	/**
2	 * One likelihood, with the range that says how sure we are of it — or, when
3	 * there is no likelihood, the absence and the reason for it.
4	 *
5	 * This is the smallest component in the product and the one carrying the most
6	 * of its honesty rule, so it is worth reading in full.
7	 *
8	 * **Two significant figures and the range, always.** A likelihood is printed as
9	 * `.35` and never as `.348` — a third figure claims an accuracy nobody has —
10	 * and it is never printed without the range under it. The rounding happens
11	 * here, once, at the moment of display; everything upstream carries the number
12	 * at full precision so that nothing is rounded twice.
13	 *
14	 * **What the range means, said out loud.** It is *how sure we are of the
15	 * number*, not how much the world can move. How much the world can move is
16	 * already inside the likelihood itself. That distinction is not a footnote: a
17	 * reader who takes a wide range to mean a volatile event has been misled by the
18	 * interface, so the model chip says which it is in its own label and spells it
19	 * out in full when you look at it.
20	 *
21	 * **An absent number is an absence, never a blank.** There is no path through
22	 * this component that prints nothing, prints a zero, or prints a stand-in. A
23	 * slot with no number shows the words for its absence and carries the reason
24	 * for it. A claim standing on the reader's own say-so shows the word — *Supposed
25	 * · Oct 1* — because while it is supposed it is true in every simulated world
26	 * and there is no number to show.
27	 */
28	
29	import { useId, useState } from "react";
30	import { type LikelihoodStep, likelihoodStep } from "../graph/wires/encodings";
31	import type { BeliefOwner, Slot, Standing } from "../world";
32	import "./beliefChip.css";
33	
34	/**
35	 * Print a number to two significant figures, the way this product prints one.
36	 *
37	 * A likelihood is between zero and one, so the leading zero is dropped: `.35`,
38	 * not `0.35`. Two significant figures means two digits that carry information,
39	 * and both of them are always printed — `.060` keeps its trailing nought,
40	 * because dropping it would claim less precision than we have, and "two figures
41	 * except when the second is a nought" would be a second rule for one ugly case.
42	 *
43	 * **It never prints a certainty.** Rounding to two figures turns .995 into
44	 * `1.0`, and nothing at all into `.0`, and both are claims nobody on this map
45	 * is entitled to make: one says the thing cannot fail, the other that it cannot
46	 * happen. So those two print as what they actually are, `>.99` and `<.01`. The
47	 * upper guard catches everything from .995 up, including 1 itself. The lower
48	 * one is rarer than it looks: two figures keeps two digits however small the
49	 * number gets, so `.0035` prints `.0035` and `.00012` prints `.00012`, and the
50	 * only value that would ever print as `.0` is exactly zero.
51	 *
52	 * **Why it does not use the obvious shortcut.** A computer stores .995 as
53	 * 0.99499999999999999556, so asking it directly for two figures gives `.99` —
54	 * under the guard, and the chip would print the one thing the rule forbids. So
55	 * the rounding is done on the number's own decimal digits instead: the shortest
56	 * decimal that reads back as this exact number, its point shifted by counting
57	 * rather than by multiplying, and then rounded half-up. `.995` shifts to
58	 * exactly 99.5, which rounds to 100, which is 1, which is `>.99`.
59	 *
60	 * @param value A likelihood, at full precision.
61	 * @returns The number as it is shown on screen.
62	 */
63	export function toTwoFigures(value: number): string {
64	  if (!Number.isFinite(value) || value <= 0) {
65	    return "<.01";
66	  }
67	  if (value >= 1) {
68	    return ">.99";
69	  }
70	  // The shortest decimal that reads back as this exact number, split into its
71	  // digits and where the point sits: .995 becomes "9.95" and -1.
72	  const [mantissa = "0", place = "0"] = value.toExponential().split("e");
73	  let exponent = Number(place);
74	  // The two figures, as a whole number from 10 to 99. Shifting the point in the
75	  // text and letting the parser read the result is what keeps .995 at 99.5
76	  // rather than a hair under it.
77	  let figures = Math.round(Number(`${mantissa}e1`));
78	  if (figures >= 100) {
79	    // Rounding up carried into the next place: .0999 becomes .10, not .100.
80	    figures = 10;
81	    exponent += 1;
82	  }
83	  if (exponent >= 0) {
84	    return ">.99";
85	  }
86	  return `.${"0".repeat(-exponent - 1)}${figures}`;
87	}
88	
89	/**
90	 * Print a range the way this product prints one: `.22–.50`.
91	 *
92	 * The dash is an en dash, the one used for a span between two numbers.
93	 */
94	export function toRange(lo: number, hi: number): string {
95	  return `${toTwoFigures(lo)}–${toTwoFigures(hi)}`;
96	}
97	
98	/**
99	 * The whole reading, in the form a sentence would use: `.35 (.22–.50)`.
100	 *
101	 * This is what the chip is called when it is read aloud, and what the tile uses
102	 * when it needs the reading inside a longer sentence.
103	 */
104	export function toReading(p: number, lo: number, hi: number): string {
105	  return `${toTwoFigures(p)} (${toRange(lo, hi)})`;
106	}
107	
108	/** The word each owner is called by on screen. */
109	const OWNER_WORDS: Record<BeliefOwner, string> = {
110	  model: "model",
111	  user: "user",
112	  market: "market",
113	};
114	
115	/**
116	 * The note a chip opens when you look at it: one label, one sentence.
117	 *
118	 * It is not a pop-up. It is a shelf that slides out from the bottom edge of the
119	 * tile, drawn on the tile's own surface, and it needs no dismissing — look
120	 * away, or move the keyboard on, and it closes itself.
121	 */
122	interface Note {
123	  /** The chip's label, printed as the first line of the shelf. */
124	  readonly label: string;
125	  /** The sentence under it. */
126	  readonly sentence: string;
127	}
128	
129	/** Group a count in thousands the way the sentence below writes it: `2 000`. */
130	function inThousands(count: number): string {
131	  return count.toLocaleString("en-GB").replace(/,/g, " ");
132	}
133	
134	/**
135	 * What the model chip says about itself — and there are two answers, because
136	 * there are two different things a range can be.
137	 *
138	 * **When a world computed these numbers**, the range came out of running the
139	 * map many times over, each run a coherent set of numbers the model would have
140	 * stood behind, and the sentence says so and then admits in its last clause
141	 * that nobody has checked the claim against anything that resolved.
142	 *
143	 * **When nothing computed them** — which is every number in this build, because
144	 * the engine's route does not exist yet — the range is what whoever wrote the
145	 * number down said about how sure they were. Saying "across 2 000 versions of
146	 * this map" over a number nobody ran through a map would be the plainest kind
147	 * of lie this product can tell, so it says the other thing instead.
148	 *
149	 * The chip picks between them by one fact: whether the world it is drawing
150	 * reports how many versions were run. Nothing else changes when the engine
151	 * lands.
152	 */
153	function modelNote(p: number, lo: number, hi: number, versions: number | undefined): Note {
154	  if (versions === undefined) {
155	    return {
156	      label: "stated range · not computed",
157	      sentence:
158	        "This range is stated, not computed — it says how sure the elicitation was. " +
159	        "Nothing has worked this number through the map yet.",
160	    };
161	  }
162	  return {
163	    label:
164	      `model interval, uncalibrated · how sure we are of ${toTwoFigures(p)} — ` +
