/**
 * One likelihood, with the range that says how sure we are of it — or, when
 * there is no likelihood, the absence and the reason for it.
 *
 * This is the smallest component in the product and the one carrying the most
 * of its honesty rule, so it is worth reading in full.
 *
 * **Two significant figures and the range, always.** A likelihood is printed as
 * `.35` and never as `.348` — a third figure claims an accuracy nobody has —
 * and it is never printed without the range under it. The rounding happens
 * here, once, at the moment of display; everything upstream carries the number
 * at full precision so that nothing is rounded twice.
 *
 * **What the range means, said out loud.** It is *how sure we are of the
 * number*, not how much the world can move. How much the world can move is
 * already inside the likelihood itself. That distinction is not a footnote: a
 * reader who takes a wide range to mean a volatile event has been misled by the
 * interface, so the model chip says which it is in its own label and spells it
 * out in full when you look at it.
 *
 * **An absent number is an absence, never a blank.** There is no path through
 * this component that prints nothing, prints a zero, or prints a stand-in. A
 * slot with no number shows the words for its absence and carries the reason
 * for it. A claim standing on the reader's own say-so shows the word — *Supposed
 * · Oct 1* — because while it is supposed it is true in every simulated world
 * and there is no number to show.
 */

import { useId, useState } from "react";
import { type LikelihoodStep, likelihoodStep } from "../graph/wires/encodings";
import type { BeliefOwner, Slot, Standing } from "../world";
import "./beliefChip.css";

/**
 * Print a number to two significant figures, the way this product prints one.
 *
 * A likelihood is between zero and one, so the leading zero is dropped: `.35`,
 * not `0.35`. Two significant figures means two digits that carry information,
 * and both of them are always printed — `.060` keeps its trailing nought,
 * because dropping it would claim less precision than we have, and "two figures
 * except when the second is a nought" would be a second rule for one ugly case.
 *
 * **It never prints a certainty.** Rounding to two figures turns .995 into
 * `1.0`, and nothing at all into `.0`, and both are claims nobody on this map
 * is entitled to make: one says the thing cannot fail, the other that it cannot
 * happen. So those two print as what they actually are, `>.99` and `<.01`. The
 * upper guard catches everything from .995 up, including 1 itself. The lower
 * one is rarer than it looks: two figures keeps two digits however small the
 * number gets, so `.0035` prints `.0035` and `.00012` prints `.00012`, and the
 * only value that would ever print as `.0` is exactly zero.
 *
 * **Why it does not use the obvious shortcut.** A computer stores .995 as
 * 0.99499999999999999556, so asking it directly for two figures gives `.99` —
 * under the guard, and the chip would print the one thing the rule forbids. So
 * the rounding is done on the number's own decimal digits instead: the shortest
 * decimal that reads back as this exact number, its point shifted by counting
 * rather than by multiplying, and then rounded half-up. `.995` shifts to
 * exactly 99.5, which rounds to 100, which is 1, which is `>.99`.
 *
 * @param value A likelihood, at full precision.
 * @returns The number as it is shown on screen.
 */
export function toTwoFigures(value: number): string {
  if (!Number.isFinite(value) || value <= 0) {
    return "<.01";
  }
  if (value >= 1) {
    return ">.99";
  }
  // The shortest decimal that reads back as this exact number, split into its
  // digits and where the point sits: .995 becomes "9.95" and -1.
  const [mantissa = "0", place = "0"] = value.toExponential().split("e");
  let exponent = Number(place);
  // The two figures, as a whole number from 10 to 99. Shifting the point in the
  // text and letting the parser read the result is what keeps .995 at 99.5
  // rather than a hair under it.
  let figures = Math.round(Number(`${mantissa}e1`));
  if (figures >= 100) {
    // Rounding up carried into the next place: .0999 becomes .10, not .100.
    figures = 10;
    exponent += 1;
  }
  if (exponent >= 0) {
    return ">.99";
  }
  return `.${"0".repeat(-exponent - 1)}${figures}`;
}

/**
 * Print a range the way this product prints one: `.22–.50`.
 *
 * The dash is an en dash, the one used for a span between two numbers.
 */
export function toRange(lo: number, hi: number): string {
  return `${toTwoFigures(lo)}–${toTwoFigures(hi)}`;
}

/**
 * The whole reading, in the form a sentence would use: `.35 (.22–.50)`.
 *
 * This is what the chip is called when it is read aloud, and what the tile uses
 * when it needs the reading inside a longer sentence.
 */
export function toReading(p: number, lo: number, hi: number): string {
  return `${toTwoFigures(p)} (${toRange(lo, hi)})`;
}

/** The word each owner is called by on screen. */
const OWNER_WORDS: Record<BeliefOwner, string> = {
  model: "model",
  user: "user",
  market: "market",
};

/**
 * The note a chip opens when you look at it: one label, one sentence.
 *
 * It is not a pop-up. It is a shelf that slides out from the bottom edge of the
 * tile, drawn on the tile's own surface, and it needs no dismissing — look
 * away, or move the keyboard on, and it closes itself.
 */
interface Note {
  /** The chip's label, printed as the first line of the shelf. */
  readonly label: string;
  /** The sentence under it. */
  readonly sentence: string;
}

/** Group a count in thousands the way the sentence below writes it: `2 000`. */
function inThousands(count: number): string {
  return count.toLocaleString("en-GB").replace(/,/g, " ");
}

/**
 * What the model chip says about itself — and there are two answers, because
 * there are two different things a range can be.
 *
 * **When a world computed these numbers**, the range came out of running the
 * map many times over, each run a coherent set of numbers the model would have
 * stood behind, and the sentence says so and then admits in its last clause
 * that nobody has checked the claim against anything that resolved.
 *
 * **When nothing computed them** — which is every number in this build, because
 * the engine's route does not exist yet — the range is what whoever wrote the
 * number down said about how sure they were. Saying "across 2 000 versions of
 * this map" over a number nobody ran through a map would be the plainest kind
 * of lie this product can tell, so it says the other thing instead.
 *
 * The chip picks between them by one fact: whether the world it is drawing
 * reports how many versions were run. Nothing else changes when the engine
 * lands.
 */
function modelNote(p: number, lo: number, hi: number, versions: number | undefined): Note {
  if (versions === undefined) {
    return {
      label: "stated range · not computed",
      sentence:
        "This range is stated, not computed — it says how sure the elicitation was. " +
        "Nothing has worked this number through the map yet.",
    };
  }
  return {
    label:
      `model interval, uncalibrated · how sure we are of ${toTwoFigures(p)} — ` +
      `not how much the world can move`,
    sentence:
      `Across ${inThousands(versions)} versions of this map — each one a set of numbers this ` +
      `model would have stood behind — the answer landed between ${toTwoFigures(lo)} and ` +
      `${toTwoFigures(hi)} eight times in ten. Nobody has checked whether that 8-in-10 holds ` +
      `up; no claim on this map has resolved yet.`,
  };
}

/** What the reader's own chip says about itself. */
function userNote(p: number, lo: number, hi: number): Note {
  return {
    label: `your own number · ${toReading(p, lo, hi)}`,
    sentence:
      "This is the number you gave. It sits beside the model's and the market's and is " +
      "never averaged with either of them.",
  };
}

/** What a market chip says about itself. */
function marketNote(lo: number, hi: number): Note {
  return {
    label: "market, as a venue is quoting it",
    sentence:
      `The likelihood is the middle of the best bid and the best offer; the range, ` +
      `${toRange(lo, hi)}, is the spread between them. It is what somebody will trade this ` +
      `claim at, not an opinion about it.`,
  };
}

/** Work out the three lines a chip shows, and the note behind it. */
function readChip(
  owner: BeliefOwner,
  slot: Slot,
  standing: Standing | undefined,
  versions: number | undefined,
): {
  reading: string;
  under: string | null;
  spoken: string;
  note: Note;
  numeric: boolean;
  step: LikelihoodStep | null;
} {
  // A claim the reader has supposed true is true in every simulated world, so
  // the chip shows the word rather than a number. Inventing one — .98, or 1.0 —
  // would invite the reader to wonder about the other two per cent of a thing
  // they themselves declared settled.
  if (standing !== undefined) {
    return {
      reading: standing.words,
      under: null,
      spoken: `${OWNER_WORDS[owner]}: ${standing.words}`,
      note: { label: standing.words, sentence: standing.reason },
      numeric: false,
      step: null,
    };
  }

  if (slot.reading === undefined) {
    const absence = slot.absence;
    return {
      reading: absence.words,
      // The reader's own empty slot says what to do about it; every other
      // absence keeps its sentence for the shelf, where there is room for it.
      under: owner === "user" ? "add yours" : null,
      spoken: `${OWNER_WORDS[owner]}: ${absence.words}. ${absence.reason}`,
      note: { label: absence.words, sentence: absence.reason },
      numeric: false,
      step: null,
    };
  }

  const { p, lo, hi } = slot.reading;
  const note =
    owner === "model"
      ? modelNote(p, lo, hi, versions)
      : owner === "user"
        ? userNote(p, lo, hi)
        : marketNote(lo, hi);
  return {
    reading: toTwoFigures(p),
    under: toRange(lo, hi),
    spoken: `${OWNER_WORDS[owner]}: ${toReading(p, lo, hi)}`,
    note,
    numeric: true,
    step: likelihoodStep(p),
  };
}

/** What a belief chip needs to draw itself. */
export interface BeliefChipProps {
  /** Whose number this is. There are three, and they are never averaged. */
  readonly owner: BeliefOwner;
  /** The number, or the absence that stands where it would have been. */
  readonly slot: Slot;
  /** A word shown instead of a likelihood, when the claim stands on the reader's say-so. */
  readonly standing?: Standing;
  /**
   * How many versions of the map were run to produce this number.
   *
   * Absent means nothing computed it, and the model chip then says so rather
   * than describing a run that never happened.
   */
  readonly versions?: number;
}

/** One of the three belief chips on a tile. */
export function BeliefChip({ owner, slot, standing, versions }: BeliefChipProps) {
  const noteId = useId();
  const [pinned, setPinned] = useState(false);
  const { reading, under, spoken, note, numeric, step } = readChip(owner, slot, standing, versions);

  return (
    <span className="belief-chip" data-owner={owner} data-reading={numeric ? "number" : "words"}>
      {/* The face of the chip is the thing you can reach, so that looking at it
          with a pointer and arriving at it with the keyboard do the same thing.
          Pressing it pins the note open, for a reader who wants both hands free
          while they read it; pressing again puts it away. It is named by the
          whole reading — the number and its range together — because that is how
          the chip would be said out loud, and the range is never left off. */}
      <button
        className="belief-chip__face"
        type="button"
        aria-label={spoken}
        aria-describedby={noteId}
        aria-controls={noteId}
        aria-expanded={pinned}
        onClick={() => setPinned((was) => !was)}
      >
        <span className="belief-chip__owner">{OWNER_WORDS[owner]}</span>
        <span className="belief-chip__reading">
          {/* The bounded bar the likelihood rides on: one of five brightnesses,
              the same size whatever the number is. Brightness is the whole of
              what it says and the number printed beside it is the reading, so
              the bar only has to clear three to one while the number clears four
              and a half. It is drawn on the chip, never over a whole tile:
              tile-wide brightness is already spent on the other world in a diff
              and on the hover lens, and three meanings on one channel means none
              of them reads. */}
          {step === null ? null : (
            <span className="belief-chip__bar" data-step={step} aria-hidden="true" />
          )}
          <span className="belief-chip__figure">{reading}</span>
        </span>
        <span className="belief-chip__under">{under ?? ""}</span>
      </button>
      <span className="belief-chip__note" id={noteId} data-pinned={pinned ? "yes" : "no"}>
        <span className="belief-chip__note-label">{note.label}</span>
        <span className="belief-chip__note-sentence">{note.sentence}</span>
      </span>
    </span>
  );
}

/**
 * The rail beside the map: the endings your edit can reach.
 *
 * An **ending** is where an argument turns into a position — a claim that names
 * something you could trade, or one that names why there is nothing to trade.
 * The rail lists the ones this edit can reach and, beside each, three things:
 * how far its number moved, **how firm** that number is, and whether it went the
 * **same direction** whatever numbers the map started from.
 *
 * **In this build all three are absences, and the order is map order.** Nothing
 * has worked a number through the map, so there is no move to report, nothing to
 * be firm about, and nothing that agreed or disagreed. And with no numbers there
 * is no ranking either — so the rail lists the endings in the order the map
 * stores them, says so on its own face, and invents nothing. A rail that made up
 * an ordering would be making up the single thing the rail exists to tell you.
 *
 * The two columns are never folded into any ordering, before the engine or
 * after it. They answer different questions and a trader weighs them separately;
 * folding the width into a rank would sink exactly the claims that most deserve
 * a second look.
 */

import { useId, useState } from "react";
import type { DeltaRow, Known } from "../world";
import "./deltaRail.css";

/** What the rail needs to draw itself. */
export interface DeltaRailProps {
  /** The endings this edit can reach, in the order the map stores them. */
  readonly rows: readonly DeltaRow[];
  /**
   * Whether something has put these rows in an order that means something.
   *
   * False in this build, and the rail says so out loud rather than letting map
   * order be mistaken for a ranking.
   */
  readonly ranked: boolean;
  /** The one line saying what this edit did to the trades, or the reason there is none. */
  readonly summary: Known<string>;
}

/** What each kind of ending is, in a word. */
const KIND_WORDS: Record<string, string> = {
  market: "tradeable",
  not_tradeable: "not tradeable",
  event: "event",
  hypothesis: "hypothesis",
};

/**
 * One cell: the number, or the words standing where it would have been.
 *
 * A cell with no number is a button, because the reason it has no number is a
 * sentence and there is no room for a sentence in a column this narrow. Pressing
 * it prints the sentence under the rail; its accessible name carries the same
 * sentence, so a reader who never sees the rail gets it without pressing
 * anything.
 */
function Cell({
  value,
  onReason,
}: {
  value: Known<string>;
  onReason: (reason: string | null) => void;
}) {
  if (value.reading !== undefined) {
    return <span className="delta-rail__value">{value.reading}</span>;
  }
  const { words, reason } = value.absence;
  return (
    <button
      className="delta-rail__value delta-rail__value--absent"
      type="button"
      aria-label={`${words}. ${reason}`}
      onClick={() => onReason(reason)}
      onFocus={() => onReason(reason)}
      onMouseEnter={() => onReason(reason)}
    >
      {words}
    </button>
  );
}

/** Turn a known number into the words a cell prints. */
function asWords(value: Known<number>): Known<string> {
  return value.reading === undefined ? { absence: value.absence } : { reading: `${value.reading}` };
}

/** The rail beside the map. */
export function DeltaRail({ rows, ranked, summary }: DeltaRailProps) {
  const [reason, setReason] = useState<string | null>(null);
  const headingId = useId();

  return (
    <section className="delta-rail" aria-labelledby={headingId}>
      <h2 className="delta-rail__heading" id={headingId}>
        Where this edit ends up
      </h2>

      {/* The one line saying what the edit did to the trades. It is written from
          the numbers the edit moved, and nothing has moved one — so it says that
          instead, and says what the map *can* tell you underneath. */}
      <p className="delta-rail__summary">
        {summary.reading ?? summary.absence.words}
        {summary.reading === undefined ? (
          <span className="delta-rail__summary-reason">{summary.absence.reason}</span>
        ) : null}
      </p>

      {rows.length === 0 ? (
        <p className="delta-rail__empty">
          No ending on this map is reachable from your edits yet. Make one — press E on a claim —
          and the endings it can reach are listed here.
        </p>
      ) : (
        <>
          <p className="delta-rail__order">
            {ranked
              ? "In the order the engine put them in: the size of the move along the best-backed route."
              : "In map order. Nothing has ranked these, because nothing has worked out a number to rank them by."}
          </p>

          <div className="delta-rail__table">
            <div className="delta-rail__labels" aria-hidden="true">
              <span>change</span>
              <span>how firm</span>
              <span>same direction</span>
            </div>
            <ul className="delta-rail__rows">
              {rows.map((row) => (
                <li className="delta-rail__row" key={row.claimId}>
                  <p className="delta-rail__label">
                    <span className="delta-rail__id">{row.claimId}</span>
                    {row.label}
                    <span className="delta-rail__kind">{KIND_WORDS[row.kind] ?? row.kind}</span>
                  </p>
                  <div className="delta-rail__values">
                    <Cell
                      value={
                        row.move.reading === undefined
                          ? { absence: row.move.absence }
                          : {
                              reading: `${row.move.reading.from} → ${row.move.reading.to}`,
                            }
                      }
                      onReason={setReason}
                    />
                    <Cell value={asWords(row.rangeWidth)} onReason={setReason} />
                    <Cell value={asWords(row.agreement)} onReason={setReason} />
                  </div>
                </li>
              ))}
            </ul>
          </div>

          <p className="delta-rail__reason">
            {reason ??
              "Every dash above carries the same reason as the words beside it. Reach one with " +
                "the keyboard, or point at it, and the reason is printed here."}
          </p>
        </>
      )}
    </section>
  );
}

/**
 * The panel beside the map: why is this number what it is.
 *
 * Every number on this canvas has to be able to say where it came from. This is
 * where it says it.
 *
 * Select a claim and the panel gives you the whole of it: the full wording, how
 * it will be judged and by whom, the outside view it started from, all three
 * beliefs with their owners kept apart, the evidence, and — once there is an
 * engine — the decomposition that turns the number into an argument you can
 * disagree with line by line. Select an arrow and it gives you the mechanism in
 * a sentence, how hard it pushes read back in words, what kind of push it is,
 * how long it takes, what it does over time, its sources with the day each was
 * fetched, and where it came from.
 *
 * **It is one persistent side panel, and there are no pop-ups anywhere in this
 * product.** A dialog you have to dismiss steals the map you were reading, and
 * the map is what makes the detail mean anything. Selecting changes what is in
 * the panel; nothing ever opens over the canvas.
 *
 * **Where a value does not exist the panel says so in words, with a reason** —
 * never a blank, never a zero, never a stand-in. In this build that reason is
 * usually *"no engine yet"*, which is an honest sentence rather than a hole.
 *
 * **The panel never works a number out.** In particular it never adds up an
 * arrow's pushes to explain a likelihood, however tempting: the pieces are all
 * there — a prior, three pushes, a result — and the moment the canvas does its
 * own arithmetic there are two engines that disagree about half a point with
 * nobody able to say which is right.
 */

import type { ReactNode } from "react";
import {
  inDays,
  likelihoodStep,
  modeInWords,
  originInWords,
  pushAsNumber,
  pushInWords,
  shapeInWords,
} from "../graph/wires/encodings";
import type {
  BeliefOwner,
  ClaimKind,
  ClaimView,
  LinkView,
  Selection,
  Slot,
  WorldView,
} from "../world";
import { toReading, toTwoFigures } from "./BeliefChip";
import { OriginMark } from "./OriginMark";
import { PathBar } from "./PathBar";
import "./inspector.css";

/**
 * What the panel needs to draw itself.
 *
 * What it is open on is a `Selection` — the same shape, under the same name, as
 * what the map draws a ring around and what the keyboard is on. One thing with
 * one name: the panel, the map and the keyboard cannot disagree about what is
 * selected if there is only one word for it.
 */
export interface InspectorProps {
  /** The map and its numbers. */
  readonly world: WorldView;
  /** What is selected. */
  readonly selection: Selection;
}

/** What each kind of claim is called on screen. No underscores and no code names. */
const KIND_WORDS: Record<ClaimKind, string> = {
  hypothesis: "hypothesis",
  event: "event",
  market: "market",
  not_tradeable: "not tradeable",
};

/** The word each owner is called by. */
const OWNER_WORDS: Record<BeliefOwner, string> = {
  model: "model",
  user: "user",
  market: "market",
};

/** A heading inside the panel: small, spaced out, and never a border of its own. */
function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="inspector__section">
      <h3 className="inspector__heading">{title}</h3>
      {children}
    </section>
  );
}

/**
 * One belief, on one line: the owner, the reading, and a bounded bar behind the
 * number painted from the five-step brightness ramp.
 *
 * The bar is a glance and never a reading. The number and its range are printed
 * beside it every time, in the text colour, so nobody is ever asked to tell one
 * step of the ramp from the next by eye — and the number always clears four and
 * a half to one while the bar only has to clear three.
 *
 * The panel writes a belief on one line; the tile stacks it over three. Same
 * number, same rounding, same guard against printing a certainty; two shapes.
 */
function BeliefRow({ owner, slot }: { owner: BeliefOwner; slot: Slot }) {
  const reading = slot.reading;
  if (reading === undefined) {
    return (
      <div className="inspector__belief" data-owner={owner}>
        <span className="inspector__owner">{OWNER_WORDS[owner]}</span>
        <span className="inspector__words">{slot.absence.words}</span>
        <span className="inspector__reason inspector__belief-reason">{slot.absence.reason}</span>
      </div>
    );
  }
  return (
    <div className="inspector__belief" data-owner={owner}>
      <span className="inspector__owner">{OWNER_WORDS[owner]}</span>
      <span className="inspector__number">
        {/* A bounded bar — always the same size — whose brightness is one of
            five steps. The bar's *length* says nothing at all, deliberately:
            length would be a second channel carrying the meaning brightness
            already carries, and the number beside it is the reading anyway. */}
        <span className="inspector__bar" data-step={likelihoodStep(reading.p)} aria-hidden="true" />
        <span className="inspector__reading">{toReading(reading.p, reading.lo, reading.hi)}</span>
      </span>
    </div>
  );
}

/**
 * What the model's range is, and which of two sentences says so.
 *
 * The range means *how sure we are of the number*, not how much the world can
 * move — the second is already inside the likelihood, and a reader who confuses
 * them reads a wide band as a volatile event.
 *
 * Which sentence sits here is decided by one field and nothing else: whether the
 * world says how many versions of the map were run. **Present**, something
 * computed this number and the range is the spread across those versions.
 * **Absent** — as here, and everywhere in this build — nothing computed it, and
 * the range is what whoever wrote the number down said about how sure they were.
 * Printing "uncalibrated" over a stated range would claim an arithmetic that
 * never ran.
 *
 * The two sentences are the belief chip's, word for word, so the tile and the
 * panel cannot drift apart.
 */
function RangeNote({ world, claim }: { world: WorldView; claim: ClaimView }) {
  const model = claim.beliefs.model.reading;
  if (model === undefined) {
    return null;
  }
  if (world.versions === undefined) {
    return (
      <>
        <p className="inspector__label">stated range · not computed</p>
        <p className="inspector__reason">
          This range is stated, not computed — it says how sure the elicitation was. Nothing has
          worked this number through the map yet.
        </p>
      </>
    );
  }
  return (
    <>
      <p className="inspector__label">
        {`model interval, uncalibrated · how sure we are of ${toTwoFigures(model.p)} — not how much the world can move`}
      </p>
      <p className="inspector__reason">
        {`Across ${world.versions.toLocaleString("en-GB").replace(/,/g, " ")} versions of this map — each one a set of numbers this model would have stood behind — the answer landed between ${toTwoFigures(model.lo)} and ${toTwoFigures(model.hi)} eight times in ten. Nobody has checked whether that 8-in-10 holds up; no claim on this map has resolved yet.`}
      </p>

      {/* ---- The reserved band slot: "why is this band wide?" -------------
          Drawn only where the range above is a *computed* one, which is what
          the test just above asks. What goes in it is one sentence naming the
          claim whose own prior explains most of the band — "92% of this band is
          B's own prior; pin that down and the band goes from 29 points to 8" —
          and it is worked out from `range_shares` on the world, which the
          engine gets out of the same two thousand versions of the map it
          already runs, at no extra cost.

          **It ships in stack 06 and nothing draws it here.** Not a placeholder
          sentence, not a greyed-out example: a sentence naming a percentage
          nobody computed is a number nobody computed wearing words. The slot is
          left in place so the layout does not jump the day the sentence
          arrives, and this comment is where the next person finds out why it is
          empty. */}
      <div className="inspector__band-slot" />
    </>
  );
}

/** A claim, top to bottom. */
function ClaimDetail({ world, claim }: { world: WorldView; claim: ClaimView }) {
  const baseRate = claim.baseRate;

  return (
    <>
      <header className="inspector__head">
        <p className="inspector__claim">{claim.claim}</p>
        <p className="inspector__kind">{KIND_WORDS[claim.kind]}</p>
      </header>

      {/* Criteria, the source that adjudicates, and the date — all three, on
          every claim. A claim nobody can score is not a claim. */}
      <Section title="Resolves">
        <p className="inspector__body">{claim.resolutionCriteria}</p>
        <dl className="inspector__pairs">
          <dt>judged by</dt>
          <dd>{claim.resolutionSource}</dd>
          <dt>by</dt>
          <dd className="inspector__mono">{claim.resolvesBy}</dd>
        </dl>
      </Section>

      <Section title="Base rate">
        {"reading" in baseRate ? (
          <>
            <p className="inspector__count">
              <span className="inspector__mono">{`${baseRate.reading.k} of ${baseRate.reading.n}`}</span>
            </p>
            <p className="inspector__body">{baseRate.reading.referenceClass}</p>
            {baseRate.reading.sources.length === 0 ? (
              <p className="inspector__reason">
                Nobody has checked this count, so nothing downstream of it may call itself
                documented.
              </p>
            ) : (
              <ul className="inspector__sources">
                {baseRate.reading.sources.map((item) => (
                  <li key={item.url} className="inspector__source">
                    <span className="inspector__source-host">{item.host}</span>
                  </li>
                ))}
              </ul>
            )}
          </>
        ) : (
          <>
            <p className="inspector__words">{baseRate.absence.words}</p>
            <p className="inspector__reason">{baseRate.absence.reason}</p>
          </>
        )}
      </Section>

      {/* The model's likelihood before this claim's causes are taken into
          account. It is here rather than on the tile because a second number
          beside the model's, on a card the size of a tile, reads as a fourth
          voice. */}
      <Section title="Prior">
        <p className="inspector__mono inspector__prior">
          {toReading(claim.prior.p, claim.prior.lo, claim.prior.hi)}
          <span className="inspector__owner"> model</span>
        </p>
      </Section>

      {/* Three voices, three owners, never merged. If the model says .61 and
          the market says .48, the gap is the thing worth trading, and .545 is a
          number nobody holds. */}
      <Section title="Beliefs">
        <BeliefRow owner="model" slot={claim.beliefs.model} />
        <RangeNote world={world} claim={claim} />
        <BeliefRow owner="user" slot={claim.beliefs.user} />
        <BeliefRow owner="market" slot={claim.beliefs.market} />
      </Section>

      <Section title="Evidence">
        {claim.evidenceInFull.length === 0 ? (
          <>
            <p className="inspector__words">—</p>
            <p className="inspector__reason">no clippings attached to this claim</p>
          </>
        ) : (
          <ul className="inspector__clippings">
            {claim.evidenceInFull.map((item) => (
              <li className="inspector__clipping" key={item.url + item.line}>
                <span className="inspector__monogram" aria-hidden="true">
                  {item.monogram}
                </span>
                <span className="inspector__sign" aria-hidden="true">
                  {item.direction === 1 ? "+" : "−"}
                </span>
                <span className="inspector__clipping-body">
                  <span className="inspector__hidden">
                    {`${item.host}, ${item.direction === 1 ? "supports this claim" : "cuts against this claim"}: `}
                  </span>
                  {item.line}
                  <span className="inspector__source-host">{item.host}</span>
                </span>
              </li>
            ))}
          </ul>
        )}
      </Section>

      {/* Where the decomposition goes: the prior, one line per incoming arrow
          with its push and its reason, then the result. It is drawn only when
          the world carries one, and no line of it is ever worked out here. */}
      <Section title="Why this number">
        <p className="inspector__words">no engine yet</p>
        <p className="inspector__reason">
          Nothing has worked this number through the map. When something has, this is where the
          prior, one line for each arrow that pushes on this claim, and the result they come to are
          printed — as the world carries them, never added up here.
        </p>
      </Section>

      <PathBar world={world} claimId={claim.id} />
    </>
  );
}

/** An arrow, read back in words. */
function WireDetail({ world, wire }: { world: WorldView; wire: LinkView }) {
  const from = world.claims.find((claim) => claim.id === wire.source);
  const to = world.claims.find((claim) => claim.id === wire.target);

  return (
    <>
      <header className="inspector__head">
        <p className="inspector__claim">
          <span className="inspector__mono">{wire.source}</span> {from?.claim ?? wire.source}
        </p>
        <p className="inspector__arrow" aria-hidden="true">
          →
        </p>
        <p className="inspector__claim">
          <span className="inspector__mono">{wire.target}</span> {to?.claim ?? wire.target}
        </p>
      </header>

      <Section title="Why">
        <p className="inspector__body">{wire.rationale}</p>
      </Section>

      <dl className="inspector__pairs inspector__pairs--wide">
        <dt>push</dt>
        <dd>
          {/* The push read back as a number and as words. Which way it pushes is
              in the last word — toward, or against — so it survives a picture
              with no colour in it. A push's sign is not a direction of financial
              effect and never takes one of those two hues. */}
          <span className="inspector__mono">{pushAsNumber(wire.strength)}</span>
          {` — ${pushInWords(wire.strength)}`}
        </dd>

        <dt>kind</dt>
        <dd>{modeInWords(wire.mode)}</dd>

        <dt>delay</dt>
        <dd>
          {wire.lag === 0
            ? "the same day its cause becomes true"
            : `${inDays(wire.lag)} after its cause becomes true`}
        </dd>

        <dt>over time</dt>
        <dd>{shapeInWords(wire.shape, wire.halfLife)}</dd>
      </dl>

      <Section title="Sources">
        {wire.sources.length === 0 ? (
          <>
            <p className="inspector__words">—</p>
            <p className="inspector__reason">
              nothing is cited for this arrow; what stands behind it is the mechanism below
            </p>
          </>
        ) : (
          <ul className="inspector__sources">
            {wire.sources.map((item) => (
              <li className="inspector__source" key={item.url}>
                <span className="inspector__source-title">{item.title}</span>
                <span className="inspector__source-host">{item.host}</span>
                <span className="inspector__source-fetched">
                  {"day" in item.retrieved ? (
                    <>
                      <span>fetched </span>
                      <span className="inspector__mono">{item.retrieved.day}</span>
                    </>
                  ) : (
                    `fetched ${item.retrieved.absence.words} ${item.retrieved.absence.reason}`
                  )}
                </span>
              </li>
            ))}
          </ul>
        )}
      </Section>

      {/* The same mark the wire draws, with the word beside it. One component,
          so the picture and the panel can never say two different things about
          the same arrow. */}
      <Section title="Where it came from">
        <p className="inspector__origin">
          <OriginMark provenance={wire.provenance} use="beside-the-word" />
          <span className="inspector__origin-word">{wire.provenance.replace("_", " ")}</span>
        </p>
        <p className="inspector__reason">{originInWords(wire.provenance)}</p>
      </Section>

      <Section title="Where it sits">
        <p className="inspector__reason">
          {wire.reflexive
            ? "This is a market acting back on the world it measures — the one kind of arrow " +
              "allowed to close a loop, which is why it must take time. It is set aside when " +
              "the map is sorted into columns and when an edit is asked what it can move; you " +
              "can still walk along it."
            : wire.mode === "sustain"
              ? "An ordinary arrow, drawn as two parallel strokes because the push only exists " +
                "while its cause holds — take the cause away and the effect goes with it."
              : "An ordinary arrow, drawn as a single stroke because the push fires once and " +
                "then fades on its own."}
        </p>
      </Section>

      {/* A path is a thing a claim has, not a thing an arrow has. The bar says
          so rather than disappearing: a missing bar looks like a bar nobody
          needed. */}
      <PathBar world={world} claimId={null} />
    </>
  );
}

/** The panel beside the map. */
export function Inspector({ world, selection }: InspectorProps) {
  const claim =
    selection?.kind === "claim" ? world.claims.find((one) => one.id === selection.id) : undefined;
  const wire =
    selection?.kind === "wire" ? world.links.find((one) => one.id === selection.id) : undefined;

  return (
    <aside className="inspector" aria-label="Why this number is what it is">
      {claim !== undefined ? (
        <ClaimDetail world={world} claim={claim} />
      ) : wire !== undefined ? (
        <WireDetail world={world} wire={wire} />
      ) : (
        <div className="inspector__empty">
          <h2 className="inspector__empty-heading">Nothing selected</h2>
          <p className="inspector__body">
            Choose a claim or an arrow on the map — click it, or reach it with the keyboard — and
            everything behind it is read out here: how it will be judged, whose numbers those are,
            what is cited for it, and where it came from.
          </p>
          <p className="inspector__reason">
            This panel is always here. Nothing in this product opens over the map.
          </p>
        </div>
      )}
    </aside>
  );
}

