1	/**
2	 * The branch panel: your edits, in the order you made them — and the six things
3	 * you can do to a claim.
4	 *
5	 * **A sequence, not a surprise.** Read as a list, the rule that a later edit
6	 * outranks an earlier supposition is obvious: you supposed the strait reopens,
7	 * then you added a strike, then you supposed the strike lands, and the strike's
8	 * arrow was added *after* the supposition, so it is live. Met instead as a number
9	 * that moved on its own, the same rule reads as a bug. So the sequence is on the
10	 * screen.
11	 *
12	 * **Edits are appended, never rewritten.** There is no way to edit an edit here,
13	 * and that is deliberate: the branch is the audit trail, and an audit trail you
14	 * can edit is not one.
15	 *
16	 * **The buttons build a branch and show it. They do not move a number.** Moving
17	 * numbers means running the map again, which is the engine's work; this half
18	 * does none of it. So pressing a button appends an edit, the panel shows it
19	 * immediately, the map redraws what your edit can reach — and every likelihood
20	 * your edit would have moved reads its absence and says why.
21	 *
22	 * **Nothing here opens over the map.** No dialog, no scrim, nothing to dismiss:
23	 * the fields below appear inside this panel, beside the map, which stays live.
24	 */
25	
26	import { useState } from "react";
27	import { toDay } from "../graph/diff/days";
28	import { pushAsNumber, pushInWords } from "../graph/wires/encodings";
29	import type { BranchView, Edit, Selection, WorldView } from "../world";
30	import "./branchPanel.css";
31	
32	/**
33	 * The six buttons, word for word from the shared vocabulary's *Interface words*
34	 * table, and the badge each one earns.
35	 *
36	 * Copied, never paraphrased. The six operations keep their code names in the
37	 * code, in the wire format and in the spec, and **not one of those names ever
38	 * appears on screen.**
39	 */
40	const BUTTONS = {
41	  supposeTrue: "Suppose this is true",
42	  supposeFalse: "Suppose this is false",
43	  happened: "This happened",
44	  addClaim: "Add a claim",
45	  changePush: "Change this push",
46	  splitClaim: "Split this claim",
47	  ownNumber: "My own number",
48	} as const;
49	
50	/** How one edit reads in the list: which button made it, and what it was about. */
51	function editLine(edit: Edit, world: WorldView): { button: string; about: string; badge: string } {
52	  const words = (id: string): string => world.claims.find((claim) => claim.id === id)?.claim ?? id;
53	  switch (edit.op) {
54	    case "do":
55	      return {
56	        button: edit.value ? BUTTONS.supposeTrue : BUTTONS.supposeFalse,
57	        about: words(edit.target),
58	        badge: `Supposed · ${toDay(edit.at)}`,
59	      };
60	    case "observe":
61	      return {
62	        button: BUTTONS.happened,
63	        about: words(edit.target),
64	        badge: `Happened · ${toDay(edit.at)}`,
65	      };
66	    case "insert":
67	      return { button: BUTTONS.addClaim, about: edit.words, badge: "Added" };
68	    case "retune":
69	      return {
70	        button: BUTTONS.changePush,
71	        about:
72	          `You moved this arrow from ${pushAsNumber(edit.wasStrength)} to ` +
73	          `${pushAsNumber(edit.strength)} — ${pushInWords(edit.strength)}.`,
74	        badge: "Retuned",
75	      };
76	    case "refine":
77	      return { button: BUTTONS.splitClaim, about: words(edit.target), badge: "Split" };
78	    case "believe":
79	      return {
80	        button: BUTTONS.ownNumber,
81	        about: words(edit.target),
82	        badge: "",
83	      };
84	  }
85	}
86	
87	/** What the branch panel needs. */
88	export interface BranchPanelProps {
89	  /** Every branch on this map, in the order they arrived. */
90	  readonly branches: readonly BranchView[];
91	  /** Which branch is open, or `null` for the map as it was written. */
92	  readonly openId: string | null;
93	  /** The world on screen, so an edit can be read back in the claim's own words. */
94	  readonly world: WorldView;
95	  /** Open a branch, or go back to the map as it was written. */
96	  readonly onOpen: (id: string | null) => void;
97	  /** Start a new branch with this name. */
98	  readonly onFork: (label: string) => void;
99	  /** Whether the name field is open, because `B` opens it from the map. */
100	  readonly naming: boolean;
101	  /** Open or close the name field. */
102	  readonly onNaming: (open: boolean) => void;
103	}
104	
105	/** The branch panel. */
106	export function BranchPanel({
107	  branches,
108	  openId,
109	  world,
110	  onOpen,
111	  onFork,
112	  naming,
113	  onNaming,
114	}: BranchPanelProps) {
115	  const [name, setName] = useState("");
116	  const open = branches.find((branch) => branch.id === openId);
117	
118	  return (
119	    <section className="branch-panel" aria-label="Your branches">
120	      <h2 className="branch-panel__heading">Branches</h2>
121	
122	      <ul className="branch-panel__list">
123	        <li>
124	          <button
125	            className="branch-panel__branch"
126	            type="button"
127	            data-open={openId === null ? "yes" : "no"}
128	            onClick={() => onOpen(null)}
129	          >
130	            <span className="branch-panel__chip" data-hue="base" aria-hidden="true" />
131	            <span className="branch-panel__name">The map as it was written</span>
132	          </button>
133	        </li>
134	        {branches.map((branch) => (
135	          <li key={branch.id}>
136	            <button
137	              className="branch-panel__branch"
138	              type="button"
139	              data-open={openId === branch.id ? "yes" : "no"}
140	              onClick={() => onOpen(branch.id)}
141	            >
142	              {/* A branch's hue is on its chip and its lane and nowhere else, and
143	                  the chip always carries the branch's name — so which branch you
144	                  are in is readable with no colour at all. */}
145	              <span className="branch-panel__chip" data-hue={branch.hue} aria-hidden="true" />
146	              <span className="branch-panel__name">{branch.label}</span>
147	              <span className="branch-panel__count">
148	                {branch.edits.length === 1 ? "1 edit" : `${branch.edits.length} edits`}
149	              </span>
150	            </button>
151	          </li>
152	        ))}
153	      </ul>
154	
155	      {naming ? (
156	        <form
157	          className="branch-panel__naming"
158	          onSubmit={(event) => {
159	            event.preventDefault();
160	            const label = name.trim();
161	            if (label !== "") {
162	              onFork(label);
163	              setName("");
164	              onNaming(false);
165	            }
166	          }}
167	        >
168	          <label className="branch-panel__field-label" htmlFor="branch-name">
169	            What is this branch called? An unnamed branch is unusable once there are three.
170	          </label>
171	          <input
172	            className="branch-panel__field"
173	            id="branch-name"
174	            value={name}
175	            // biome-ignore lint/a11y/noAutofocus: the reader pressed B to open this field and the next thing they will do is type into it; sending focus anywhere else is a keystroke thrown away.
176	            autoFocus
177	            onChange={(event) => setName(event.target.value)}
178	          />
179	          <div className="branch-panel__field-actions">
180	            <button className="branch-panel__go" type="submit">
181	              Start this branch
182	            </button>
183	            <button
184	              className="branch-panel__cancel"
185	              type="button"
186	              onClick={() => {
187	                setName("");
188	                onNaming(false);
189	              }}
190	            >
191	              Not now
192	            </button>
193	          </div>
194	        </form>
195	      ) : (
196	        <button className="branch-panel__fork" type="button" onClick={() => onNaming(true)}>
197	          Start a branch
198	        </button>
199	      )}
200	
201	      {open === undefined ? (
202	        <p className="branch-panel__none">
203	          Nothing has been edited. The map above is exactly as it was written, and every number on
204	          it is the one the stored example carries.
205	        </p>
206	      ) : (
207	        <ol className="branch-panel__edits">
208	          {open.edits.map((edit, index) => {
209	            const line = editLine(edit, world);
210	            return (
211	              // biome-ignore lint/suspicious/noArrayIndexKey: a branch is append-only — no edit is ever rewritten, removed or reordered — so an edit's place in the list is a stable name for it, and it is the name the panel prints beside it.
212	              <li className="branch-panel__edit" key={`${index}-${line.button}`}>
213	                <span className="branch-panel__number">{index + 1}</span>
214	                <span className="branch-panel__about">
215	                  <span className="branch-panel__button-name">{line.button}</span>
216	                  <span className="branch-panel__subject">{line.about}</span>
217	                </span>
218	                {line.badge === "" ? (
219	                  <span className="branch-panel__no-badge">
220	                    no badge — the three-up belief chip is the badge
221	                  </span>
222	                ) : (
223	                  <span className="branch-panel__badge">{line.badge}</span>
224	                )}
225	              </li>
226	            );
227	          })}
228	        </ol>
229	      )}
230	    </section>
231	  );
232	}
