/**
 * The path bar: how likely the whole chain is, and which chain that was.
 *
 * A chain of four plausible steps is not a plausible chain. Every step in a map
 * like this one is something somebody found believable on its own, and the
 * number that says what the four of them come to together is the number the map
 * exists to produce. So whenever a claim is selected, the panel shows one route
 * from the hypothesis to it and the multiplied-out likelihood of that route's
 * steps beside the story.
 *
 * **This bar renders. It never multiplies.** The product arrives on the world,
 * computed where the map's numbers are computed. A canvas that multiplied its
 * own would be a second engine, and two engines disagree about half a point with
 * nobody able to say which is right. There is no multiplication anywhere in this
 * file; when the number is missing, the bar says so and stops.
 *
 * **Three things the bar can say, and they are not the same thing.**
 *
 *   1. **The number**, when the world carries one.
 *   2. **"no path shown"** — nothing is selected, or no route was asked for.
 *      This is the absent-number case, and it says which absence it is.
 *   3. **"no path from the hypothesis reaches this claim any more"** — a fact
 *      about the map rather than about our plumbing. It used to be a state on
 *      the tile and it is not one: it is a property of the *route*, so it lives
 *      here, where routes live.
 *
 * The bar never disappears. A missing bar looks like a bar nobody needed.
 *
 * **The honest wart, said beside the number rather than hidden.** The factors of
 * the product are each read on their own resolve-by day, so the product
 * multiplies numbers read on different days. It is still the most honest single
 * number available for a chain, and **it is not the chance of the whole chain
 * happening together.** The bar says that in those words.
 */

import { originStep } from "../graph/wires/encodings";
import type { ClaimView, LinkView, WorldView } from "../world";
import { toTwoFigures } from "./BeliefChip";
import "./pathBar.css";

/** One step of a route: the arrow taken, and the claim it lands on. */
export interface RouteStep {
  /** The arrow walked along. */
  readonly wire: LinkView;
  /** The claim it lands on. */
  readonly claim: ClaimView;
}

/** A route from the hypothesis to a claim, and how well backed its weakest arrow is. */
export interface Route {
  /** Where the route starts. */
  readonly from: ClaimView;
  /** Each arrow taken and the claim it lands on, in order. */
  readonly steps: readonly RouteStep[];
}

/** How a route being looked for turned out. */
type Search =
  | { readonly found: true; readonly route: Route }
  | { readonly found: false; readonly why: "is-the-hypothesis" | "nothing-reaches-it" };

/** What one claim's best route so far looks like while the search is running. */
interface Best {
  /** How well backed the weakest arrow on this route is: three dots, two or one. */
  readonly bottleneck: number;
  /** How many arrows it takes. */
  readonly length: number;
  /** The arrows, in order. */
  readonly wires: readonly LinkView[];
}

/**
 * Is this route better than the one we had?
 *
 * **The best-backed route**: over every route from the hypothesis to the claim,
 * the one whose *weakest arrow is strongest* — the widest bottleneck. A chain is
 * only as well backed as its flimsiest step, so the route worth showing is the
 * one whose flimsiest step is the least flimsy. Where two routes tie, the
 * shorter one wins, and where they tie on that too, the one the map lists first.
 *
 * "Best backed" is measured by the receipt on each arrow — whether something was
 * fetched, whether a mechanism was stated, or whether it is the model talking —
 * which is a rank of three, not a number. Comparing two ranks is not arithmetic
 * on the map's numbers, and no push or likelihood is read anywhere in this
 * search.
 *
 * @param candidate The route just found.
 * @param incumbent The best route found so far, if any.
 */
function isBetter(candidate: Best, incumbent: Best | undefined): boolean {
  if (incumbent === undefined) {
    return true;
  }
  if (candidate.bottleneck !== incumbent.bottleneck) {
    return candidate.bottleneck > incumbent.bottleneck;
  }
  return candidate.length < incumbent.length;
}

/**
 * The best-backed route from the hypothesis to this claim.
 *
 * **Feedback arrows are set aside.** The rule is written once, in the chapter on
 * interventions: the map the engine works through is the map with feedback
 * arrows set aside, and anything asking *what can move* reads that map. A
 * likelihood flowing along a chain is exactly that question, so a claim reached
 * only through a feedback arrow has no route here — and the bar says so in
 * words rather than leaving a hole.
 *
 * @param world The map and its numbers.
 * @param claimId The claim the panel is open on.
 */
export function bestBackedRoute(world: WorldView, claimId: string): Search {
  if (claimId === world.hypothesisId) {
    return { found: false, why: "is-the-hypothesis" };
  }
  const claims = new Map(world.claims.map((claim) => [claim.id, claim]));
  const walkable = world.links.filter((link) => !link.reflexive);

  const best = new Map<string, Best>();
  best.set(world.hypothesisId, { bottleneck: Number.POSITIVE_INFINITY, length: 0, wires: [] });

  // Relax every arrow until nothing improves. The maps this runs on have a
  // handful of claims, so the simplest correct search is the right one.
  let changed = true;
  let rounds = 0;
  while (changed && rounds <= walkable.length) {
    changed = false;
    rounds += 1;
    for (const wire of walkable) {
      const upTo = best.get(wire.source);
      if (upTo === undefined) {
        continue;
      }
      const step = originStep(wire.provenance);
      const candidate: Best = {
        bottleneck: Math.min(upTo.bottleneck, step),
        length: upTo.length + 1,
        wires: [...upTo.wires, wire],
      };
      if (isBetter(candidate, best.get(wire.target))) {
        best.set(wire.target, candidate);
        changed = true;
      }
    }
  }

  const found = best.get(claimId);
  const from = claims.get(world.hypothesisId);
  if (found === undefined || from === undefined) {
    return { found: false, why: "nothing-reaches-it" };
  }
  const steps: RouteStep[] = [];
  for (const wire of found.wires) {
    const landed = claims.get(wire.target);
    if (landed === undefined) {
      return { found: false, why: "nothing-reaches-it" };
    }
    steps.push({ wire, claim: landed });
  }
  return { found: true, route: { from, steps } };
}

/** What the bar needs to draw itself. */
export interface PathBarProps {
  /** The map and its numbers. */
  readonly world: WorldView;
  /** The claim the panel is open on, or `null` when it is open on an arrow or on nothing. */
  readonly claimId: string | null;
}

/** The line of identifiers a route reads as: `H → B → M1`. */
function routeLine(route: Route): string {
  return [route.from.id, ...route.steps.map((step) => step.claim.id)].join(" → ");
}

/** The bar beside the story: one route, and what its steps come to together. */
export function PathBar({ world, claimId }: PathBarProps) {
  if (claimId === null) {
    return (
      <section className="path-bar" aria-label="How likely the whole chain is">
        <h3 className="path-bar__heading">Path from the hypothesis</h3>
        <p className="path-bar__reading" data-reading="no-path-shown">
          no path shown
        </p>
        <p className="path-bar__why">
          A path is shown for a claim. Select one on the map and this bar names the route from the
          hypothesis to it.
        </p>
      </section>
    );
  }

  const claim = world.claims.find((one) => one.id === claimId);
  const search = bestBackedRoute(world, claimId);

  if (!search.found) {
    return (
      <section className="path-bar" aria-label="How likely the whole chain is">
        <h3 className="path-bar__heading">Path from the hypothesis</h3>
        <p className="path-bar__reading" data-reading="no-route">
          {search.why === "is-the-hypothesis"
            ? "no path shown"
            : "no path from the hypothesis reaches this claim any more"}
        </p>
        <p className="path-bar__why">
          {search.why === "is-the-hypothesis"
            ? "This is the claim the map starts from. There is no route into it, because " +
              "nothing on the map comes before it."
            : "Every arrow that could carry the hypothesis to this claim is a feedback " +
              "arrow — a market acting back on the world it measures — and a chain's " +
              "likelihood is read on the map with those set aside. You can still walk to " +
              "this claim along the wires; nothing can push it."}
        </p>
      </section>
    );
  }

  const { route } = search;
  // The absence and its reason come from the world, and the bar prints them. It
  // does not fall back to working the number out; there is nothing here that
  // could.
  const product = claim?.pathProduct;
  const reading = product?.reading;

  return (
    <section className="path-bar" aria-label="How likely the whole chain is">
      <h3 className="path-bar__heading">Path from the hypothesis</h3>

      <p className="path-bar__route">{routeLine(route)}</p>

      <ol className="path-bar__steps">
        <li className="path-bar__step">
          <span className="path-bar__step-id">{route.from.id}</span>
          <span className="path-bar__step-claim">{route.from.claim}</span>
        </li>
        {route.steps.map((step) => (
          <li className="path-bar__step" key={step.wire.id}>
            <span className="path-bar__step-id">{step.claim.id}</span>
            <span className="path-bar__step-claim">{step.claim.claim}</span>
          </li>
        ))}
      </ol>

      <p className="path-bar__label">path likelihood</p>
      {reading === undefined ? (
        <>
          <p className="path-bar__reading" data-reading="no-number">
            {product?.absence.words ?? "no engine yet"}
          </p>
          <p className="path-bar__why">
            {product?.absence.reason ?? "Nothing has worked this number through the map yet."}
          </p>
        </>
      ) : (
        <p className="path-bar__reading" data-reading="number">
          {toTwoFigures(reading.p)}
        </p>
      )}

      <p className="path-bar__wart">
        Each step of this route is read on its own resolve-by day, so the number multiplies
        likelihoods read on different days. It is the most honest single number there is for a
        chain, and it is not the chance of the whole chain happening together.
      </p>
    </section>
  );
}

/**
 * The branches you have made, and the one rule that governs them: **edits are
 * appended, never rewritten.**
 *
 * A branch is a named, ordered list of edits over a base map. It holds no
 * likelihoods and no results — everything a branch shows on screen is worked out
 * from the base map plus this list, which is what makes the original safe to
 * leave untouched and what makes the whole thing replayable.
 *
 * **Why nothing here ever edits an edit in place.** The branch is the audit
 * trail. Press *Suppose this is true* on a claim, then press *Change this push*
 * on an arrow, and the two edits sit in the panel in that order — and the
 * surprising rule that a later addition outranks an earlier supposition reads as
 * a sequence rather than as a number that moved on its own. An audit trail you
 * can edit is not one. So every function below hands back a new branch whose
 * earlier edits are the very same objects, and there is no function that
 * replaces one.
 *
 * **Nothing here moves a number.** These functions build a list. Working out
 * what the list does to the map's likelihoods is the engine's job, and this half
 * of the product does none of it.
 */

import type { BranchHue, BranchView, Edit } from "./types";

/**
 * The branches on one map, and which of them is open.
 *
 * `openId` of `null` is the base world — the empty branch, the map as it was
 * written.
 */
export interface Workshop {
  /** Every branch on this map, in the order they arrived. */
  readonly branches: readonly BranchView[];
  /** Which branch is open, or `null` for the base world. */
  readonly openId: string | null;
}

/**
 * The four hues a branch may take, in the order they are handed out.
 *
 * Never amber: amber already means "the money moves down", and one hue cannot
 * mean two things. A fifth branch reuses the first hue rather than inventing a
 * fifth — every branch also carries a name chip with its label, so which branch
 * you are in is readable with no colour at all.
 */
const HUES: readonly BranchHue[] = ["violet", "teal", "rose", "slate"];

/**
 * Start from the branches a map arrived with, none of them open.
 *
 * @param branches The branches the map itself carries.
 */
export function workshopOf(branches: readonly BranchView[]): Workshop {
  return { branches, openId: null };
}

/**
 * Open a branch, or go back to the base world.
 *
 * @param shop The branches as they stand.
 * @param id The branch to open, or `null` for the base world.
 */
export function openBranch(shop: Workshop, id: string | null): Workshop {
  if (id !== null && !shop.branches.some((branch) => branch.id === id)) {
    return shop;
  }
  return { ...shop, openId: id };
}

/**
 * Make a new branch and open it.
 *
 * The new branch forks off the base map with no edits in it. It takes the next
 * hue in the list above, and its label is what the reader typed.
 *
 * @param shop The branches as they stand.
 * @param label What the reader is calling this branch. An unnamed branch is
 *   unusable once there are three of them.
 */
export function forkBranch(shop: Workshop, label: string): Workshop {
  const hue = HUES[shop.branches.length % HUES.length] ?? "violet";
  const made: BranchView = {
    id: `branch-${shop.branches.length + 1}`,
    label,
    hue,
    edits: [],
    claims: [],
    links: [],
  };
  return { branches: [...shop.branches, made], openId: made.id };
}

/**
 * Add one edit to the open branch, at the end.
 *
 * Every edit already in the branch comes through as the same object it was, so
 * that "nothing earlier was rewritten" is a property you can check by identity
 * rather than by reading fields back.
 *
 * @param shop The branches as they stand.
 * @param edit The edit the reader just made.
 * @returns The branches with the edit appended. Unchanged when no branch is
 *   open: the base map is never edited, and a branch is what an edit goes into.
 */
export function appendEdit(shop: Workshop, edit: Edit): Workshop {
  if (shop.openId === null) {
    return shop;
  }
  return {
    ...shop,
    branches: shop.branches.map((branch) =>
      branch.id === shop.openId ? { ...branch, edits: [...branch.edits, edit] } : branch,
    ),
  };
}

/**
 * The plate in the middle of a wire: what this arrow does, read back in words.
 *
 * **What it will eventually show** is the *conditional likelihood* — how likely
 * this arrow's target is with its cause supposed true — which is the one number
 * that turns an arrow into something you can argue about. That number is not on
 * the map and is not worked out here. It costs a whole extra run of the map per
 * arrow, so the engine works one out only when a wire is asked about, one at a
 * time, and the answer is cached.
 *
 * **Until it has one — and always, in this build, because that route does not
 * exist yet — the chip reads the arrow's push back in words**, which is data
 * already on the arrow and needs no arithmetic:
 *
 *     +1.6
 *     a strong push toward
 *     after 2 days
 *
 * **Never a guessed number.** Not the push converted into a likelihood, not the
 * target's current number, not a dash that looks like a number that failed to
 * load. A number nobody computed is exactly the state a reader cannot trace.
 *
 * The delay is on the plate as well as in the panel. It is data on the arrow, it
 * needs no arithmetic, and it is the one thing on this map that says time
 * passes — which is most of what makes a chain of causes read as a chain rather
 * than as a diagram.
 */

import { toRange, toTwoFigures } from "../../components/BeliefChip";
import type { Slot } from "../../world";
import { lagInWords, likelihoodStep, pushAsNumber, pushInWords } from "./encodings";

/** What the chip needs to draw itself. */
export interface WireChipProps {
  /** How hard this arrow pushes, signed, at full precision. */
  readonly strength: number;
  /** Days from the cause becoming true to the push reaching full size. */
  readonly lag: number;
  /**
   * The likelihood of this arrow's target with its cause supposed true.
   *
   * Absent in this build, and the chip then reads the push in words. It is a
   * parameter rather than an assumption so that the day the engine answers,
   * this component already knows what to do with it.
   */
  readonly conditional: Slot;
  /**
   * How much of the plate there is room for.
   *
   * Below the zoom at which a tile switches to its summary, thirteen-pixel words
   * would land under eleven pixels on the glass — so the plate changes what it
   * draws rather than drawing it smaller, exactly as the tile does. The summary
   * is the signed push alone, set in the largest size, which clears the floor
   * all the way down to the zoom floor. The words and the delay are one click
   * away in the panel, and the stroke still says what kind of push it is.
   */
  readonly detail: "full" | "summary";
  /**
   * The shape of the room this plate has.
   *
   * A wire that crosses one gutter has a tall narrow strip to sit in, so its
   * plate stacks: the push, then the words, then the delay. A wire that travels
   * a corridor between two rows of tiles, or runs over the top of the map, has a
   * wide short strip instead, so its plate lies along the wire on one line. Same
   * three things, laid out for the space rather than squeezed into it.
   */
  readonly layout: "stacked" | "inline";
  /**
   * True when this is the one arrow that runs backwards — a market acting back
   * on the world it measures.
   *
   * It changes one thing: such an arrow keeps its delay on the plate even when
   * the map is zoomed out far enough that every other plate has dropped to the
   * push alone. A loop that takes no time is not feedback, it is a
   * contradiction, so the time is the part of that arrow that may not go.
   */
  readonly reflexive: boolean;
}

/** The plate in the middle of a wire. */
export function WireChip({ strength, lag, conditional, detail, layout, reflexive }: WireChipProps) {
  if (detail === "summary") {
    return (
      <span className="wire-chip" data-reading="push" data-detail="summary" data-layout={layout}>
        <span className="wire-chip__push">{pushAsNumber(strength)}</span>
        {reflexive ? <span className="wire-chip__lag">{lagInWords(lag)}</span> : null}
      </span>
    );
  }

  // There is no path through this component that prints a likelihood nobody
  // computed. When the engine can answer, its answer lands in the first branch
  // below; until then the slot holds its absence and the arrow's own push is
  // what the plate reads.
  const answer = conditional.reading;
  if (answer !== undefined) {
    return (
      <span className="wire-chip" data-reading="likelihood" data-detail="full" data-layout={layout}>
        <span className="wire-chip__bar" data-step={likelihoodStep(answer.p)} aria-hidden="true" />
        <span className="wire-chip__push">{toTwoFigures(answer.p)}</span>
        <span className="wire-chip__words">with its cause supposed true</span>
        <span className="wire-chip__lag">{toRange(answer.lo, answer.hi)}</span>
      </span>
    );
  }

  return (
    <span className="wire-chip" data-reading="push" data-detail="full" data-layout={layout}>
      <span className="wire-chip__push">{pushAsNumber(strength)}</span>
      <span className="wire-chip__words">{pushInWords(strength)}</span>
      <span className="wire-chip__lag">{lagInWords(lag)}</span>
    </span>
  );
}

/**
 * One arrow on the map, drawn so that the picture says what the arrow says.
 *
 * Five things at once, and **not one of them is a colour**:
 *
 * | What | How it is drawn | What survives a grey print |
 * |---|---|---|
 * | What kind of push it is | The stroke's pattern: dot-dash for a one-time spike, solid for a switch that holds, dashes that grow for one that builds | the pattern |
 * | How hard it pushes | The stroke's width, in four steps, from the size of the push regardless of its sign | the width |
 * | Whether it has to keep holding | Two parallel strokes when it does, one when it fires once | the doubling |
 * | Whether it loops back | It runs over the top of the map and carries the delay | the loop |
 * | Where it came from | A mark of one, two or three dots at the tail | the count of dots |
 *
 * **The stroke says one thing and one thing only: what kind of push this is.**
 * It used to be asked to carry where the arrow came from as well, and it cannot:
 * a wire cannot be dot-dash because it is a spike and dashed because it was
 * merely argued at the same time — it would be neither, legibly. One channel per
 * meaning. So where it came from moved to the mark at the tail, and the exact
 * word of the seven moved to the panel, where there is room for it.
 *
 * **A push's sign is not a direction of financial effect**, and this file is
 * where that matters most. The arrow into *Brent settles below $68* is `+1.6` —
 * positive, because it makes that claim come out true more often — and the
 * price it describes is falling. Colour that arrow amber and you have said the
 * opposite of what it means. So no wire reads a direction colour, ever; the sign
 * is printed and the word says *toward* or *against*.
 *
 * Nothing here does arithmetic on the map's numbers. Choosing a width or a band
 * of words is a comparison against fixed thresholds, and everything else in this
 * file is pixel geometry.
 */

import {
  BaseEdge,
  type Edge,
  EdgeLabelRenderer,
  type EdgeProps,
  getSmoothStepPath,
} from "@xyflow/react";
import { OriginMark } from "../../components/OriginMark";
import type { LinkMode, LinkShape, Provenance, Slot } from "../../world";
import { strokeFor, widthFor } from "./encodings";
import { MARK_STANDOFF } from "./plates";
import {
  corridorCorners,
  longestRunMidpoint,
  type Point,
  type RoutePlan,
  roundedPath,
  skyCorners,
} from "./route";
import { WireChip } from "./WireChip";
import "./wires.css";

/** Everything a wire needs beyond where its two ends are. */
export interface WireData extends Record<string, unknown> {
  /** What the push does over time. The stroke's pattern, and nothing else. */
  readonly shape: LinkShape;
  /** How hard it pushes, signed, at full precision. The stroke's width. */
  readonly strength: number;
  /** Whether the push survives its cause going away. Doubled when it does. */
  readonly mode: LinkMode;
  /** Days from the cause becoming true to the push reaching full size. */
  readonly lag: number;
  /** True when this arrow is a market feeding back on the world. */
  readonly reflexive: boolean;
  /** Where the arrow and its number came from. The mark at the tail. */
  readonly provenance: Provenance;
  /** The likelihood with this arrow's cause supposed true. Absent in this build. */
  readonly conditional: Slot;
  /** How this wire gets from one end to the other, worked out from the layout. */
  readonly plan?: RoutePlan;
  /** True when the hover lens has put this wire off the path. */
  readonly dimmed?: boolean;
  /** True when the map is zoomed out far enough that a plate's words would be too small. */
  readonly tooSmallForWords?: boolean;
  /**
   * How far the mark at this arrow's tail is moved off the wire, so that two
   * arrows leaving the same socket do not draw their marks on top of each other.
   */
  readonly tailOffset?: number;
  /**
   * Where this wire's plate goes, worked out for the whole map at once.
   *
   * A wire cannot see its neighbours, and on a map with two worlds laid over
   * each other that is not enough: plates began landing on one another. So the
   * spot is decided in one pass over every wire — `plates.ts` — and handed in.
   * Left out, the wire falls back to placing its own, which is what it does when
   * it is drawn on its own in a test.
   */
  readonly plateAt?: { readonly x: number; readonly y: number };
  /**
   * Which column of the map this wire belongs to, for the one animation the map
   * spends on causality.
   *
   * The wire itself is revealed by a stylesheet rule keyed on a class the canvas
   * puts on it. Its plate and its mark are drawn in another layer entirely, so
   * they are given the same delay here — otherwise the reading arrives a beat
   * before the wire it is a reading of.
   */
  readonly wave?: number;
}

/** A wire as the canvas knows it. */
export type CausalEdge = Edge<WireData, "causal">;

/**
 * How far the plate is nudged along the wire, away from the mark at its tail.
 *
 * The gutter between one column and the next is 120 pixels, and it has to hold
 * both: the mark takes the first twenty at the tail end, and the plate takes the
 * rest. Without the nudge the plate would sit in the middle of the gutter and
 * swallow the mark.
 */
const PLATE_NUDGE = 16;

/** How round a corner drawn by the library's own router is. */
const CORNER = 8;

/**
 * How tall a stacked plate is, near enough.
 *
 * Only used to decide whether a wire drops far enough for its plate to sit in
 * the middle of the drop. Nothing is positioned by it, so it does not have to be
 * exact — and it is written down here rather than measured off the drawn plate,
 * because measuring would make where a plate goes depend on the order the page
 * happened to draw things in.
 */
const PLATE_HEIGHT = 96;

/** How far clear of the wire a plate sits when it cannot sit on it. */
const PLATE_STANDOFF = 8;

/** The class names that carry a wire's five encodings into the stylesheet. */
function wireClasses(data: WireData, width: number, selected: boolean): string {
  return [
    "wire",
    `wire--${data.shape}`,
    `wire--${data.mode}`,
    `wire--step-${width}`,
    data.reflexive ? "wire--reflexive" : "",
    data.dimmed ? "is-dimmed" : "",
    selected ? "is-selected" : "",
  ]
    .filter((one) => one !== "")
    .join(" ");
}

/** What a wire draws on the glass rather than in the drawing: its mark and its plate. */
export interface WireLabelsProps {
  /** Everything the wire knows about the arrow. */
  readonly data: WireData;
  /** Where the wire leaves its cause. */
  readonly sourceX: number;
  /** The height it leaves at. */
  readonly sourceY: number;
  /** Where the plate sits. */
  readonly plateAt: Point;
  /** The shape of the room the plate has. */
  readonly plateLayout: "stacked" | "inline";
  /** Where the plate's own box is pinned to the point it was given. */
  readonly plateAnchor: string;
  /** True when the panel beside the map is open on this arrow. */
  readonly selected: boolean;
}

/**
 * The mark at the tail and the plate in the middle.
 *
 * These are drawn as ordinary page elements rather than as part of the drawing,
 * because words set in a drawing cannot wrap, cannot be read out by a screen
 * reader as words, and cannot be styled from the same stylesheet as the rest of
 * the interface. They are its own component so that they can be looked at on
 * their own, without a whole map around them.
 */
export function WireLabels({
  data,
  sourceX,
  sourceY,
  plateAt,
  plateLayout,
  plateAnchor,
  selected,
}: WireLabelsProps) {
  // The wire itself is revealed a column at a time by a rule in `canvas.css`,
  // keyed on a class the canvas puts on it. Its plate and its mark are drawn in
  // another layer, outside that rule's reach, so they are given the same delay
  // here — otherwise the reading of a wire arrives before the wire.
  const waveDelay = {
    "--wave-delay": `calc(${data.wave ?? 0} * var(--duration-stagger))`,
  } as React.CSSProperties;

  return (
    <>
      {/* The mark that says where this arrow came from, at the tail, where the
          arrow leaves its cause. The head already has the arrowhead, and a
          receipt belongs where the claim was made. */}
      <div
        className="wire-mark"
        data-dimmed={data.dimmed ? "yes" : "no"}
        style={{
          ...waveDelay,
          transform:
            `translate(0, -50%) translate(${sourceX + MARK_STANDOFF}px, ` +
            `${sourceY + (data.tailOffset ?? 0)}px)`,
        }}
      >
        <OriginMark provenance={data.provenance} use="alone" />
      </div>

      {/* The plate. Below the zoom at which a tile switches to its summary it
          switches to its own: the signed push alone, set large enough to clear
          the eleven-pixel floor all the way down. The tile does the same thing
          at the same threshold, and the answer in both cases is to draw less
          rather than to draw it smaller. */}
      <div
        className="wire-plate"
        data-detail={data.tooSmallForWords ? "summary" : "full"}
        data-layout={plateLayout}
        data-dimmed={data.dimmed ? "yes" : "no"}
        data-selected={selected ? "true" : "false"}
        style={{
          ...waveDelay,
          transform: `translate(-50%, ${plateAnchor}) translate(${plateAt[0]}px, ${plateAt[1]}px)`,
        }}
      >
        <WireChip
          strength={data.strength}
          lag={data.lag}
          conditional={data.conditional}
          detail={data.tooSmallForWords ? "summary" : "full"}
          layout={plateLayout}
          reflexive={data.reflexive}
        />
      </div>
    </>
  );
}

/**
 * Draw one wire.
 *
 * The stroke is painted twice for an arrow that has to keep holding: once wide
 * in the wire's own ink, and once narrower in the colour of the page, which
 * leaves two parallel lines with a clear gap down the middle. Both passes use
 * the same dashes, so the gap only appears where there is ink to split.
 */
export function CausalWire({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  sourcePosition,
  targetPosition,
  markerEnd,
  selected,
  data,
}: EdgeProps<CausalEdge>) {
  if (data === undefined) {
    return null;
  }
  const plan: RoutePlan = data.plan ?? { kind: "direct" };
  const drawing = strokeFor(data.shape);
  const width = widthFor(data.strength);

  // Where the wire goes, and where its plate sits. The ordinary route is the
  // drawing library's own; the other two are ours, because the library has no
  // idea where the tiles ended up and would take both of them straight through
  // one — and a wire that disappears behind a tile has told the reader that the
  // tile causes what the wire causes, which is a lie the picture tells all by
  // itself.
  let path: string;
  let chipAt: Point;
  if (plan.kind === "direct") {
    const [drawn, labelX, labelY] = getSmoothStepPath({
      sourceX,
      sourceY,
      targetX,
      targetY,
      sourcePosition,
      targetPosition,
      borderRadius: CORNER,
    });
    path = drawn;
    chipAt = [labelX, labelY];
  } else {
    const corners =
      plan.kind === "sky"
        ? skyCorners(sourceX, sourceY, targetX, targetY, plan.skyY)
        : corridorCorners(sourceX, sourceY, targetX, targetY, plan);
    path = roundedPath(corners);
    chipAt = longestRunMidpoint(corners);
  }

  const doubled = data.mode === "sustain";
  // Two parallel lines of `width`, with a clear gap between them, come to one
  // stroke of twice the width plus the gap — with the gap painted back out in
  // the colour of the page.
  const outer = doubled ? width * 2 + 2 : width;
  const dashes = drawing.dashes ?? undefined;
  // Measured in hundredths of this wire's own length when the pattern has to run
  // its course exactly once from tail to head, whatever the wire's length.
  const pathLength = drawing.growsAlongTheWire ? 100 : undefined;

  // Where the plate sits, which is three different answers for the three routes.
  //
  // A wire that takes the ordinary route crosses one gutter, and that gutter has
  // to hold the mark at the tail as well as the plate — so the plate moves along
  // the wire, away from the tail.
  //
  // A wire that skips a column turns into its corridor in the gutter just after
  // its cause, and a gutter is the one strip of the map with nothing in it. The
  // plate goes there rather than halfway along the corridor, which would put it
  // over the tile the corridor runs past.
  //
  // A wire that runs over the top of the map has nothing but sky around it.
  // A wire that crosses one gutter drops as far as its two sockets are apart,
  // and on this map that is anything from two pixels to five hundred. Where the
  // drop is long the plate sits in the middle of it and the wire shows above and
  // below. Where it is short there is no middle to sit in, and a plate on the
  // wire would cover the whole of it — so the plate steps up and sits just clear
  // of the wire instead, and what the stroke says can be read again.
  const drop = targetY > sourceY ? targetY - sourceY : sourceY - targetY;
  const ridesAside = plan.kind === "direct" && drop < PLATE_HEIGHT;
  // **Which side it steps to is decided by the socket the wire leaves.** A tile
  // has two: an arrow that fires once leaves the upper one and an arrow that has
  // to keep holding leaves the lower one. So the first kind's plates take the
  // space above the wire and the second kind's take the space below, and two
  // plates from one tile can never land on each other — or on the marks at the
  // other socket's tails, which is what went wrong before this rule existed.
  const asideBelow = ridesAside && data.mode === "sustain";
  const ownPlateAt: Point = asideBelow
    ? [chipAt[0], (targetY > sourceY ? targetY : sourceY) + PLATE_STANDOFF]
    : ridesAside
      ? [chipAt[0], (targetY < sourceY ? targetY : sourceY) - PLATE_STANDOFF]
      : plan.kind === "direct"
        ? [chipAt[0] + PLATE_NUDGE, chipAt[1]]
        : plan.kind === "corridor"
          ? [(plan.fromX + plan.toX) / 2, plan.corridorY]
          : chipAt;

  // The spot the whole-map pass gave this plate, when there was one. It is
  // already the middle of the plate's box, so nothing is pinned to an edge.
  const planned = data.plateAt;
  const plateAt: Point = planned === undefined ? ownPlateAt : [planned.x, planned.y];

  /** Where the plate's own box is pinned to the point above. */
  const plateAnchor =
    planned !== undefined ? "-50%" : asideBelow ? "0" : ridesAside ? "-100%" : "-50%";

  const plateLayout = plan.kind === "direct" ? "stacked" : "inline";

  return (
    <>
      <BaseEdge
        id={id}
        path={path}
        markerEnd={markerEnd}
        className={wireClasses(data, width, selected === true)}
        style={{ strokeWidth: outer, strokeDasharray: dashes }}
        pathLength={pathLength}
      />
      {doubled ? (
        // The gap down the middle. It is the same path drawn again, narrower and
        // in the colour of the page, which turns one stroke into two.
        <path
          className="wire__split"
          d={path}
          style={{ strokeDasharray: dashes }}
          pathLength={pathLength}
        />
      ) : null}

      <EdgeLabelRenderer>
        <WireLabels
          data={data}
          sourceX={sourceX}
          sourceY={sourceY}
          plateAt={plateAt}
          plateLayout={plateLayout}
          plateAnchor={plateAnchor}
          selected={selected === true}
        />
      </EdgeLabelRenderer>
    </>
  );
}

