1	/**
2	 * The map: tiles, wires, panning and zooming.
3	 *
4	 * The drawing library owns four things and no more — panning, zooming, working
5	 * out what is under the pointer, and the sockets on the sides of a tile.
6	 * Everything you can see is ours. That is why only the library's bare
7	 * stylesheet is imported below and never its full one: the full one carries the
8	 * library's own look, and a tool that looks like the library it was built with
9	 * looks like a demo. A check in `npm run lint` fails the build if the full one
10	 * ever appears in this tree.
11	 *
12	 * Three things this file works out that no single wire could work out for
13	 * itself, because a wire cannot see where the other tiles are:
14	 *
15	 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
16	 *      take the ordinary route. An arrow that skips a column would run straight
17	 *      through the tile in between and disappear behind it, so it is given a
18	 *      clear corridor to travel along instead; and the one arrow that runs
19	 *      backwards is sent over the top of the map, where there is nothing to
20	 *      cross.
21	 *   2. **The hover lens.** Point at a claim and everything not on its path —
22	 *      neither one of its causes nor one of the things it causes — drops to
23	 *      fifteen per cent.
24	 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
25	 *      which a tile switches to its summary, a plate's words would land under
26	 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
27	 *      dodge the rule.
28	 */
29	
30	import {
31	  Background,
32	  BackgroundVariant,
33	  Controls,
34	  ReactFlow,
35	  ReactFlowProvider,
36	  useReactFlow,
37	  useStore,
38	} from "@xyflow/react";
39	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
40	import "@xyflow/react/dist/base.css";
41	import { Tile } from "../components/Tile";
42	import { TileOverflow } from "../components/TileOverflow";
43	import type { MapKeys } from "../keyboard/useMapKeys";
44	import { useMapKeys } from "../keyboard/useMapKeys";
45	import type { Selection, WorldView } from "../world";
46	import {
47	  firstFrame,
48	  LARGEST_ZOOM,
49	  SMALLEST_ZOOM,
50	  SUMMARY_BELOW_ZOOM,
51	  TILE_WIDTH,
52	} from "./geometry";
53	import { assignLayers } from "./layers";
54	import { useLayout } from "./layoutRunner";
55	import {
56	  type ClaimNode,
57	  type MapEdge,
58	  type MapNode,
59	  OVERFLOW_PREFIX,
60	  type OverflowNode,
61	  toFlow,
62	} from "./toFlow";
63	import { CausalWire } from "./wires/CausalWire";
64	import { onThePathFrom } from "./wires/lens";
65	import { planPlates } from "./wires/plates";
66	import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
67	import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
68	import "./canvas.css";
69	
70	/** The two kinds of box the map draws. Defined once, outside render, so the
71	 * drawing library never has to rebuild its tiles because the object changed. */
72	const TILE_TYPES = {
73	  claim: ({ data }: { data: ClaimNode["data"] }) => (
74	    <Tile
75	      claim={data.claim}
76	      isHypothesis={data.isHypothesis}
77	      versions={data.versions}
78	      height={data.height}
79	    />
80	  ),
81	  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
82	};
83	
84	/** One kind of wire, ours, saying five things at once. */
85	const WIRE_TYPES = { causal: CausalWire };
86	
87	/** What the map needs beyond the world it draws. */
88	interface SurfaceProps {
89	  /** The world to draw. */
90	  readonly world: WorldView;
91	  /** What the panel beside the map is open on. */
92	  readonly selection: Selection;
93	  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
94	  readonly onSelect: (selection: Selection) => void;
95	  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
96	  readonly focused: string | null;
97	  /** Put the keyboard on a claim. */
98	  readonly onFocused: (id: string | null) => void;
99	  /**
100	   * How tall to draw each tile, when a diff needs one box to hold two paintings.
101	   * Left out, each tile is as tall as its own content.
102	   */
103	  readonly heights?: ReadonlyMap<string, number>;
104	  /**
105	   * Which map this is: the base map, or the base map with one branch folded on.
106	   *
107	   * Both paintings of one diff share it, so flipping between them moves nothing.
108	   * Opening a different branch changes it, and the union of the two worlds is
109	   * then laid out again from scratch — one layout, two paintings.
110	   */
111	  readonly mapKey: string;
112	  /** Everything the keys that are not about moving are wired to. */
113	  readonly keys: MapKeys;
114	  /** Say what the last keystroke did, under the map. */
115	  readonly onStatus: (line: string) => void;
116	  /**
117	   * The reader asked to see the claims a column had no room for.
118	   *
119	   * The collapsed tile does not expand: it opens the outline, filtered to that
120	   * column. The outline is built from the world rather than from what is
121	   * painted, so those claims already have items there and the tile only has to
122	   * point at them.
123	   */
124	  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
125	  /**
126	   * True while the map is arriving, which is when the one animation it spends on
127	   * causality runs: the wires draw in the order the argument runs, a column at a
128	   * time. Under reduced motion the ordering survives and the drawing goes.
129	   */
130	  readonly arriving: boolean;
131	}
132	
133	/** The surface itself. Lives inside the provider so it can move the view. */
134	function MapSurface({
135	  world,
136	  selection,
137	  onSelect,
138	  focused,
139	  onFocused,
140	  heights,
141	  mapKey,
142	  keys,
143	  onStatus,
144	  onOverflow,
145	  arriving,
146	}: SurfaceProps) {
147	  const flow = useReactFlow();
148	  const surface = useRef<HTMLDivElement>(null);
149	  const [pointingAt, setPointingAt] = useState<string | null>(null);
150	
151	  const drawing = useMemo(() => toFlow(world, heights), [world, heights]);
152	  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);
153	
154	  // How far the map is zoomed out. Below the threshold a wire's plate would
155	  // have its words drawn under eleven pixels on the glass, which is the one
156	  // thing nothing in this product is allowed to do, so the plates go and the
157	  // stroke keeps saying what kind of push each wire is.
158	  const zoom = useStore((state) => state.transform[2]);
159	  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;
160	
161	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
162	  const heightOf = useCallback(
163	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
164	    [drawing],
165	  );
166	
167	  /** Where every tile ended up, which is what routing a wire needs to know. */
168	  const boxes = useMemo(() => {
169	    const placed = new Map<string, Box>();
170	    for (const [id, at] of layout.positions) {
171	      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
172	    }
173	    return placed;
174	  }, [layout, heightOf]);
175	
176	  // What the hover lens leaves lit. `null` is everything, which is what the map
177	  // looks like when the reader is not pointing at anything. The claim the
178	  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
179	  // feature.
180	  const lens = useMemo(
181	    () => onThePathFrom(pointingAt ?? focused, world.links),
182	    [pointingAt, focused, world.links],
183	  );
184	
185	  // Which column each claim sits in, for the one animation this map spends on
186	  // causality: the wires arrive in the order the argument runs, a column at a
187	  // time. The order is read from the map's own shape, never from the clock.
188	  const column = useMemo(() => {
189	    const placed = new Map<string, number>();
190	    for (const one of assignLayers(
191	      world.claims.map((claim) => claim.id),
192	      world.links,
193	    )) {
194	      placed.set(one.id, one.layer);
195	    }
196	    return placed;
197	  }, [world]);
198	
199	  const nodes: MapNode[] = useMemo(
200	    () =>
201	      drawing.nodes.map((node) => {
202	        const ghost = node.type === "claim" && node.data.claim.ghost === true;
203	        return {
204	          ...node,
205	          position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
206	          selected: selection?.kind === "claim" && selection.id === node.id,
207	          // Two classes and not one: the hover lens and the other world are both
208	          // opacity, and a tile that is off the hovered path *and* in the other
209	          // world has to land at the two multiplied together rather than at
210	          // whichever rule happened to win. `canvas.css` multiplies them.
211	          className: [
212	            lens !== null && !lens.claims.has(node.id) ? "is-dimmed" : "",
213	            ghost ? "is-ghost" : "",
214	          ]
215	            .filter((one) => one !== "")
216	            .join(" "),
217	        };
218	      }),
219	    [drawing, layout, lens, selection],
220	  );
221	
222	  const edges: MapEdge[] = useMemo(() => {
223	    const routable = drawing.edges.map((edge) => ({
224	      id: edge.id,
225	      source: edge.source,
226	      target: edge.target,
227	      handle: edge.sourceHandle ?? "out-trigger",
228	      reflexive: edge.data?.reflexive === true,
229	      mode: edge.data?.mode ?? "trigger",
230	      strength: edge.data?.strength ?? 0,
231	      lag: edge.data?.lag ?? 0,
232	    }));
233	    const plans = planRoutes(routable, boxes);
234	    const offsets = tailOffsets(routable);
235	    // Where every plate goes, worked out for the whole map at once. A wire
236	    // cannot see its neighbours, and once two worlds are laid over each other
237	    // that is not enough: the union crowds the middle of the map and plates
238	    // began landing on one another.
239	    const plates = planPlates({ wires: routable, boxes, plans, tailOffsets: offsets });
240	    const wires = new Map(world.links.map((link) => [link.id, link]));
241	    return drawing.edges.map((edge) => {
242	      if (edge.data === undefined) {
243	        return edge;
244	      }
245	      const wire = wires.get(edge.id);
246	      return {
247	        ...edge,
248	        selected: selection?.kind === "wire" && selection.id === edge.id,
249	        // The wave's place in the order, and whether this wire belongs to the
250	        // world you are not looking at. Both are carried as classes, because a
251	        // class is what the drawing library puts on the group the wire is drawn
252	        // in, and a wire cannot know where the other wires are.
253	        className: [
254	          `wave-${Math.min(column.get(edge.source) ?? 0, 5)}`,
255	          wire?.ghost === true ? "is-ghost" : "",
256	          wire?.change === undefined ? "" : `is-${wire.change}`,
257	        ]
258	          .filter((one) => one !== "")
259	          .join(" "),
260	        data: {
261	          ...edge.data,
262	          plan: plans.get(edge.id),
263	          tailOffset: offsets.get(edge.id),
264	          plateAt: plates.get(edge.id),
265	          wave: Math.min(column.get(edge.source) ?? 0, 5),
266	          dimmed: lens !== null && !lens.wires.has(edge.id),
267	          tooSmallForWords,
268	        },
269	      };
270	    });
271	  }, [drawing, boxes, lens, selection, tooSmallForWords, world, column]);
272	
273	  /**
274	   * Everything the first frame has to hold: every tile, and the strip of empty
275	   * space above them that the one backwards wire runs along.
276	   */
277	  const mapBounds = useCallback(() => {
278	    const placed = [...layout.positions.entries()];
279	    if (placed.length === 0) {
280	      return null;
281	    }
282	    const left = Math.min(...placed.map(([, at]) => at.x));
283	    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
284	    const top = Math.min(...placed.map(([, at]) => at.y));
285	    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
286	    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
287	    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
288	  }, [drawing, layout, heightOf]);
289	
290	  const framed = useRef<string | null>(null);
291	  const justFramed = useRef(false);
292	  const centredOn = useRef<string | null>(null);
293	
294	  // Frame the map when it is a different map — the first time it is drawn, and
295	  // again when a branch adds a claim to it. Panning, zooming and walking around
296	  // never re-frame: losing your place because the map was rearranged is the most
297	  // disorienting thing a canvas can do.
298	  useEffect(() => {
299	    // Only once the positions really are this map's. Framing from the positions
300	    // worked out for the map before the branch would frame the wrong thing, and
301	    // the right thing would then arrive underneath it.
302	    if (layout.runs === 0 || layout.laidOutFor !== mapKey || framed.current === mapKey) {
303	      return;
304	    }
305	    const frame = mapBounds();
306	    const room = surface.current?.getBoundingClientRect();
307	    if (frame === null || room === undefined) {
308	      return;
309	    }
310	    // Framed to fit — but never zoomed out past the point where a full tile would
311	    // have to become a summary. The reader's first sight of the map is tiles they
312	    // can read; if the whole map does not fit at that size, it is framed from its
313	    // beginning, on the left, where the map starts, and they pan to the rest.
314	    flow.setViewport(firstFrame(frame, { width: room.width, height: room.height }), {
315	      duration: 0,
316	    });
317	    framed.current = mapKey;
318	    justFramed.current = true;
319	  }, [layout.runs, layout.laidOutFor, flow, mapBounds, mapKey]);
320	
321	  // The view follows whatever the keyboard is on, so a step along a wire never
322	  // walks off the edge of the glass. It does not fight the framing above: when a
323	  // branch has just arrived and moved focus to the claim it added, the whole map
324	  // has already been framed and that claim is in it.
325	  useEffect(() => {
326	    if (focused === null || layout.runs === 0 || centredOn.current === focused) {
327	      // Only when the keyboard has actually moved. Flipping between the two
328	      // worlds redraws every tile and moves none of them, and a view that slid
329	      // sideways on the flip would make the reader hunt for what changed — which
330	      // is the one thing the flip exists to show.
331	      return;
332	    }
333	    if (justFramed.current) {
334	      justFramed.current = false;
335	      centredOn.current = focused;
336	      return;
337	    }
338	    const node = flow.getNode(focused);
339	    if (node === undefined) {
340	      return;
341	    }
342	    centredOn.current = focused;
343	    flow.setCenter(node.position.x + TILE_WIDTH / 2, node.position.y + heightOf(focused) / 2, {
344	      zoom: flow.getZoom(),
345	      duration: 0,
346	    });
347	  }, [focused, flow, heightOf, layout.runs]);
348	
349	  /** Show the claims a column had no room for, as a list. */
350	  const openColumn = useCallback(
351	    (layer: number) => {
352	      onOverflow({
353	        layer,
354	        claims: [...column.entries()].filter(([, at]) => at === layer).map(([id]) => id),
355	      });
356	      onStatus(`the claims in column ${layer}, as a list`);
357	    },
358	    [column, onOverflow, onStatus],
359	  );
360	
361	  /**
362	   * What the reader just pointed at, or `null` when it was the empty map.
363	   *
364	   * Read off the page rather than from the drawing library, deliberately. The
365	   * library reports a click on a tile only through the machinery that also drags
366	   * tiles around, and tiles here do not drag — so that report never arrives.
367	   * Asking the page what was under the pointer is one line, and it gives the
368	   * same answer for a wire, a tile and the empty map.
369	   */
370	  const whatIsUnder = useCallback((target: HTMLElement | null): Selection => {
371	    const wire = target?.closest<HTMLElement>(".react-flow__edge");
372	    if (wire?.dataset.id !== undefined) {
373	      return { kind: "wire", id: wire.dataset.id };
374	    }
375	    const tile = target?.closest<HTMLElement>(".react-flow__node");
376	    if (tile?.dataset.id !== undefined) {
377	      return { kind: "claim", id: tile.dataset.id };
378	    }
379	    return null;
380	  }, []);
381	
382	  /**
383	   * Fill the panel with whatever was pressed, or empty it on a press on the map.
384	   *
385	   * It listens for the press rather than the click, and that is not a detail:
386	   * the drawing library grabs the pointer on the surface the moment a press
387	   * begins, so that dragging the map keeps working when the pointer wanders off
388	   * a tile — and from then on every event, the click included, is reported
389	   * against the surface rather than against what was actually under the pointer.
390	   * The press is the last moment the page can still say what was pressed.
391	   */
392	  const onPointAt = useCallback(
393	    (event: React.PointerEvent<HTMLDivElement>) => {
394	      const under = whatIsUnder(event.target as HTMLElement);
395	      // The zoom buttons and the library's own furniture are not the map.
396	      if (under === null && (event.target as HTMLElement).closest(".react-flow__controls")) {
397	        return;
398	      }
399	      if (under?.kind === "claim" && under.id.startsWith(OVERFLOW_PREFIX)) {
400	        openColumn(Number(under.id.slice(OVERFLOW_PREFIX.length)));
401	        return;
402	      }
403	      onSelect(under);
404	      if (under?.kind === "claim") {
405	        onFocused(under.id);
406	        // Pointing at a tile and reaching it with the keyboard land in the same
407	        // place, so the ring says where you are whichever way you got there.
408	        (event.target as HTMLElement)
409	          .closest<HTMLElement>(".react-flow__node")
410	          ?.focus({ preventScroll: true });
411	      }
412	    },
413	    [onSelect, whatIsUnder, onFocused, openColumn],
414	  );
415	
416	  /**
417	   * Remember what the reader is on, fill the panel with it, and bring it into
418	   * view if it is off the edge of the screen.
419	   *
420	   * This catches the keyboard as well as the pointer. Reaching a claim or an
421	   * arrow with the keyboard and reaching it with the pointer do the same thing:
422	   * the panel beside the map reads it out. Nothing opens over the map, and
423	   * there is nothing to dismiss.
424	   */
425	  const onFocus = useCallback(
426	    (event: React.FocusEvent<HTMLDivElement>) => {
427	      const target = event.target as HTMLElement;
428	      const under = whatIsUnder(target);
429	      if (under === null) {
430	        return;
431	      }
432	      if (under.kind === "wire") {
433	        // **Landing on a wire does not select it, and that is not an
434	        // oversight.** The drawing library rebuilds a wire's element when it
435	        // becomes selected, and rebuilding the element the keyboard is standing
436	        // on drops focus to the page — which made tabbing through the map
437	        // impossible, because the wires come before the tiles. So a wire fills
438	        // the panel when you press Enter on it, and the focus is put back on the
439	        // rebuilt wire straight afterwards, which is what the effect below is
440	        // for. Pointing at one with the mouse is unchanged.
441	        return;
442	      }
443	      onSelect(under);
444	      onFocused(under.id);
445	    },
446	    [onSelect, whatIsUnder, onFocused],
447	  );
448	
449	  // Where every tile ended up, in the shape moving along a wire needs: the
450	  // keyboard asks what it can *walk to*, which reads the whole map, feedback
451	  // arrows included.
452	  const places = useMemo(() => {
453	    const map = new Map<string, { x: number; y: number; height: number }>();
454	    for (const [id, at] of layout.positions) {
455	      map.set(id, { x: at.x, y: at.y, height: heightOf(id) });
456	    }
457	    return map;
458	  }, [layout, heightOf]);
459	
460	  /**
461	   * Find a tile or a wire on the glass by the identifier it carries.
462	   *
463	   * By reading each element's own identifier rather than by asking the page for
464	   * a match: a wire is named after its two ends — `H->B` — and the arrow in the
465	   * middle of that is not a character an address for an element may contain.
466	   */
467	  const onTheGlass = useCallback((kind: "node" | "edge", id: string): HTMLElement | undefined => {
468	    const all = surface.current?.querySelectorAll<HTMLElement>(`.react-flow__${kind}`) ?? [];
469	    return [...all].find((one) => one.dataset.id === id);
470	  }, []);
471	
472	  const claimWords = useCallback(
473	    (id: string) => world.claims.find((claim) => claim.id === id)?.claim ?? id,
474	    [world],
475	  );
476	
477	  const onKeyDown = useMapKeys({
478	    wires: world.links,
479	    positions: places,
480	    focused,
481	    onFocused: (id) => {
482	      onFocused(id);
483	      // Reaching a tile with the keyboard and reaching it with the pointer do
484	      // the same thing: the panel beside the map reads it out. Nothing opens
485	      // over the map.
486	      onSelect({ kind: "claim", id });
487	      onTheGlass("node", id)?.focus();
488	    },
489	    onStatus,
490	    keys,
491	    words: claimWords,
492	  });
493	
494	  // A wire the reader has just asked for, so that focus can be put back on it
495	  // once the drawing library has rebuilt it.
496	  const askedForWire = useRef<string | null>(null);
497	
498	  // biome-ignore lint/correctness/useExhaustiveDependencies: the selection is not read inside — it is what this is waiting for. The wire is rebuilt because the selection changed, so the selection is exactly the right thing to hang this on.
499	  useEffect(() => {
500	    const id = askedForWire.current;
501	    if (id === null) {
502	      return;
503	    }
504	    askedForWire.current = null;
505	    // Two frames, not none. The drawing library keeps its own record of what is
506	    // selected and rebuilds the wire's element from it a frame later, so putting
507	    // focus back on the element that is there right now would put it on the one
508	    // about to be thrown away.
509	    const frame = requestAnimationFrame(() => {
510	      requestAnimationFrame(() => onTheGlass("edge", id)?.focus());
511	    });
512	    return () => cancelAnimationFrame(frame);
513	  }, [selection, onTheGlass]);
514	
515	  // The keyboard map, bound once on the page. On the page rather than on the map
516	  // itself, because a key bound to the element you happen to be standing on is a
517	  // key that stops working the moment you press Tab — and every key below is left
518	  // alone while the keyboard is in a field.
519	  useEffect(() => {
520	    const onKey = (event: KeyboardEvent): void => {
521	      // A collapsed tile is reached with the keyboard like any other, and Enter
522	      // opens what is behind it — the same thing a press does.
523	      const target = event.target as HTMLElement | null;
524	      const at = target?.closest<HTMLElement>(".react-flow__node");
525	      if (event.key === "Enter" && at?.dataset.id?.startsWith(OVERFLOW_PREFIX) === true) {
526	        event.preventDefault();
527	        openColumn(Number(at.dataset.id.slice(OVERFLOW_PREFIX.length)));
528	        return;
529	      }
530	      // Enter on a wire reads it out in the panel beside the map — the same
531	      // thing pointing at it does. It is Enter rather than merely landing on it
532	      // because of what the comment above `onFocus` explains.
533	      const wire = target?.closest<HTMLElement>(".react-flow__edge");
534	      if ((event.key === "Enter" || event.key === " ") && wire?.dataset.id !== undefined) {
535	        event.preventDefault();
536	        askedForWire.current = wire.dataset.id;
537	        onSelect({ kind: "wire", id: wire.dataset.id });
538	        onStatus(`this arrow, read out in the panel beside the map`);
539	        return;
540	      }
541	      onKeyDown(event);
542	    };
543	    window.addEventListener("keydown", onKey);
544	    return () => window.removeEventListener("keydown", onKey);
545	  }, [onKeyDown, openColumn, onSelect, onStatus]);
546	
547	  return (
548	    <div
549	      className="canvas"
550	      ref={surface}
551	      data-arriving={arriving ? "yes" : "no"}
552	      onFocusCapture={onFocus}
553	      onPointerDownCapture={onPointAt}
554	    >
555	      <WireMarks />
556	
557	      <ReactFlow
558	        nodes={nodes}
559	        edges={edges}
560	        nodeTypes={TILE_TYPES}
561	        edgeTypes={WIRE_TYPES}
562	        // Tiles do not move. Automatic layout decides where a claim sits, and a
563	        // tile you can drag half of the time — snapping back whenever the map is
564	        // laid out again — reads as broken. Pinning, grouping and annotating
565	        // arrive later as things you ask for, not as free dragging.
566	        nodesDraggable={false}
567	        nodesConnectable={false}
568	        // A tile and a wire both answer to the pointer and to the keyboard. A
569	        // wire has to: everything it says on the glass it says again in words in
570	        // the panel, and the only way to ask for those words is to reach it.
571	        elementsSelectable={true}
572	        nodesFocusable={true}
573	        edgesFocusable={true}
574	        // Selecting a wire must not lift it above the others. The drawing
575	        // library's default is to re-sort the wires when one is selected so the
576	        // selected one draws on top — and re-sorting them moves the element the
577	        // keyboard is standing on, which drops focus to the page and makes
578	        // tabbing through the map impossible. Nothing here needs the lift: a
579	        // selected wire is marked by a ring, and how wires cross is settled by
580	        // routing rather than by drawing order.
581	        elevateNodesOnSelect={false}
582	        onNodeMouseEnter={(_, node) => setPointingAt(node.id)}
583	        onNodeMouseLeave={() => setPointingAt(null)}
584	        // As far out as the map goes, and no further: past this the summary
585	        // tile's words would be drawn smaller than anything in this product is
586	        // allowed to be.
587	        minZoom={SMALLEST_ZOOM}
588	        maxZoom={LARGEST_ZOOM}
589	        proOptions={{ hideAttribution: false }}
590	        // Named, not addressed: the drawing library writes the address around
591	        // the name itself.
592	        defaultEdgeOptions={{ markerEnd: ARROWHEAD }}
593	      >
594	        <Background variant={BackgroundVariant.Dots} gap={32} size={1} />
595	        <Controls showInteractive={false} position="bottom-left" />
596	      </ReactFlow>
597	
598	      {layout.failure === null ? null : (
599	        <p className="canvas__failure">{`The map could not be laid out. ${layout.failure}`}</p>
600	      )}
601	    </div>
602	  );
603	}
604	
605	/** What the map needs to be dropped into a page. */
606	export type MapCanvasProps = SurfaceProps;
607	
608	/** The map, ready to be dropped into a page. */
609	export function MapCanvas(props: MapCanvasProps) {
610	  return (
611	    <ReactFlowProvider>
612	      <MapSurface {...props} />
613	    </ReactFlowProvider>
614	  );
615	}
