/**
 * The map: tiles, wires, panning and zooming.
 *
 * The drawing library owns four things and no more — panning, zooming, working
 * out what is under the pointer, and the sockets on the sides of a tile.
 * Everything you can see is ours. That is why only the library's bare
 * stylesheet is imported below and never its full one: the full one carries the
 * library's own look, and a tool that looks like the library it was built with
 * looks like a demo. A check in `npm run lint` fails the build if the full one
 * ever appears in this tree.
 *
 * Three things this file works out that no single wire could work out for
 * itself, because a wire cannot see where the other tiles are:
 *
 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
 *      take the ordinary route. An arrow that skips a column would run straight
 *      through the tile in between and disappear behind it, so it is given a
 *      clear corridor to travel along instead; and the one arrow that runs
 *      backwards is sent over the top of the map, where there is nothing to
 *      cross.
 *   2. **The hover lens.** Point at a claim and everything not on its path —
 *      neither one of its causes nor one of the things it causes — drops to
 *      fifteen per cent.
 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
 *      which a tile switches to its summary, a plate's words would land under
 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
 *      dodge the rule.
 */

import {
  Background,
  BackgroundVariant,
  Controls,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
  useStore,
} from "@xyflow/react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import "@xyflow/react/dist/base.css";
import { Tile } from "../components/Tile";
import { TileOverflow } from "../components/TileOverflow";
import type { MapKeys } from "../keyboard/useMapKeys";
import { useMapKeys } from "../keyboard/useMapKeys";
import type { Selection, WorldView } from "../world";
import {
  firstFrame,
  LARGEST_ZOOM,
  SMALLEST_ZOOM,
  SUMMARY_BELOW_ZOOM,
  TILE_WIDTH,
} from "./geometry";
import { assignLayers } from "./layers";
import { useLayout } from "./layoutRunner";
import {
  type ClaimNode,
  type MapEdge,
  type MapNode,
  OVERFLOW_PREFIX,
  type OverflowNode,
  toFlow,
} from "./toFlow";
import { CausalWire } from "./wires/CausalWire";
import { onThePathFrom } from "./wires/lens";
import { planPlates } from "./wires/plates";
import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
import "./canvas.css";

/** The two kinds of box the map draws. Defined once, outside render, so the
 * drawing library never has to rebuild its tiles because the object changed. */
const TILE_TYPES = {
  claim: ({ data }: { data: ClaimNode["data"] }) => (
    <Tile
      claim={data.claim}
      isHypothesis={data.isHypothesis}
      versions={data.versions}
      height={data.height}
    />
  ),
  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
};

/** One kind of wire, ours, saying five things at once. */
const WIRE_TYPES = { causal: CausalWire };

/** What the map needs beyond the world it draws. */
interface SurfaceProps {
  /** The world to draw. */
  readonly world: WorldView;
  /** What the panel beside the map is open on. */
  readonly selection: Selection;
  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
  readonly onSelect: (selection: Selection) => void;
  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
  readonly focused: string | null;
  /** Put the keyboard on a claim. */
  readonly onFocused: (id: string | null) => void;
  /**
   * How tall to draw each tile, when a diff needs one box to hold two paintings.
   * Left out, each tile is as tall as its own content.
   */
  readonly heights?: ReadonlyMap<string, number>;
  /**
   * Which map this is: the base map, or the base map with one branch folded on.
   *
   * Both paintings of one diff share it, so flipping between them moves nothing.
   * Opening a different branch changes it, and the union of the two worlds is
   * then laid out again from scratch — one layout, two paintings.
   */
  readonly mapKey: string;
  /** Everything the keys that are not about moving are wired to. */
  readonly keys: MapKeys;
  /** Say what the last keystroke did, under the map. */
  readonly onStatus: (line: string) => void;
  /**
   * The reader asked to see the claims a column had no room for.
   *
   * The collapsed tile does not expand: it opens the outline, filtered to that
   * column. The outline is built from the world rather than from what is
   * painted, so those claims already have items there and the tile only has to
   * point at them.
   */
  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
  /**
   * True while the map is arriving, which is when the one animation it spends on
   * causality runs: the wires draw in the order the argument runs, a column at a
   * time. Under reduced motion the ordering survives and the drawing goes.
   */
  readonly arriving: boolean;
}

/** The surface itself. Lives inside the provider so it can move the view. */
function MapSurface({
  world,
  selection,
  onSelect,
  focused,
  onFocused,
  heights,
  mapKey,
  keys,
  onStatus,
  onOverflow,
  arriving,
}: SurfaceProps) {
  const flow = useReactFlow();
  const surface = useRef<HTMLDivElement>(null);
  const [pointingAt, setPointingAt] = useState<string | null>(null);

  const drawing = useMemo(() => toFlow(world, heights), [world, heights]);
  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);

  // How far the map is zoomed out. Below the threshold a wire's plate would
  // have its words drawn under eleven pixels on the glass, which is the one
  // thing nothing in this product is allowed to do, so the plates go and the
  // stroke keeps saying what kind of push each wire is.
  const zoom = useStore((state) => state.transform[2]);
  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;

  /** How tall a tile turned out to be, so the view can be centred on its middle. */
  const heightOf = useCallback(
    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
    [drawing],
  );

  /** Where every tile ended up, which is what routing a wire needs to know. */
  const boxes = useMemo(() => {
    const placed = new Map<string, Box>();
    for (const [id, at] of layout.positions) {
      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
    }
    return placed;
  }, [layout, heightOf]);

  // What the hover lens leaves lit. `null` is everything, which is what the map
  // looks like when the reader is not pointing at anything. The claim the
  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
  // feature.
  const lens = useMemo(
    () => onThePathFrom(pointingAt ?? focused, world.links),
    [pointingAt, focused, world.links],
  );

  // Which column each claim sits in, for the one animation this map spends on
  // causality: the wires arrive in the order the argument runs, a column at a
  // time. The order is read from the map's own shape, never from the clock.
  const column = useMemo(() => {
    const placed = new Map<string, number>();
    for (const one of assignLayers(
      world.claims.map((claim) => claim.id),
      world.links,
    )) {
      placed.set(one.id, one.layer);
    }
    return placed;
  }, [world]);

  const nodes: MapNode[] = useMemo(
    () =>
      drawing.nodes.map((node) => {
        const ghost = node.type === "claim" && node.data.claim.ghost === true;
        return {
          ...node,
          position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
          selected: selection?.kind === "claim" && selection.id === node.id,
          // Two classes and not one: the hover lens and the other world are both
          // opacity, and a tile that is off the hovered path *and* in the other
          // world has to land at the two multiplied together rather than at
          // whichever rule happened to win. `canvas.css` multiplies them.
          className: [
            lens !== null && !lens.claims.has(node.id) ? "is-dimmed" : "",
            ghost ? "is-ghost" : "",
          ]
            .filter((one) => one !== "")
            .join(" "),
        };
      }),
    [drawing, layout, lens, selection],
  );

  const edges: MapEdge[] = useMemo(() => {
    const routable = drawing.edges.map((edge) => ({
      id: edge.id,
      source: edge.source,
      target: edge.target,
      handle: edge.sourceHandle ?? "out-trigger",
      reflexive: edge.data?.reflexive === true,
      mode: edge.data?.mode ?? "trigger",
      strength: edge.data?.strength ?? 0,
      lag: edge.data?.lag ?? 0,
    }));
    const plans = planRoutes(routable, boxes);
    const offsets = tailOffsets(routable);
    // Where every plate goes, worked out for the whole map at once. A wire
    // cannot see its neighbours, and once two worlds are laid over each other
    // that is not enough: the union crowds the middle of the map and plates
    // began landing on one another.
    const plates = planPlates({ wires: routable, boxes, plans, tailOffsets: offsets });
    const wires = new Map(world.links.map((link) => [link.id, link]));
    return drawing.edges.map((edge) => {
      if (edge.data === undefined) {
        return edge;
      }
      const wire = wires.get(edge.id);
      return {
        ...edge,
        selected: selection?.kind === "wire" && selection.id === edge.id,
        // The wave's place in the order, and whether this wire belongs to the
        // world you are not looking at. Both are carried as classes, because a
        // class is what the drawing library puts on the group the wire is drawn
        // in, and a wire cannot know where the other wires are.
        className: [
          `wave-${Math.min(column.get(edge.source) ?? 0, 5)}`,
          wire?.ghost === true ? "is-ghost" : "",
          wire?.change === undefined ? "" : `is-${wire.change}`,
        ]
          .filter((one) => one !== "")
          .join(" "),
        data: {
          ...edge.data,
          plan: plans.get(edge.id),
          tailOffset: offsets.get(edge.id),
          plateAt: plates.get(edge.id),
          wave: Math.min(column.get(edge.source) ?? 0, 5),
          dimmed: lens !== null && !lens.wires.has(edge.id),
          tooSmallForWords,
        },
      };
    });
  }, [drawing, boxes, lens, selection, tooSmallForWords, world, column]);

  /**
   * Everything the first frame has to hold: every tile, and the strip of empty
   * space above them that the one backwards wire runs along.
   */
  const mapBounds = useCallback(() => {
    const placed = [...layout.positions.entries()];
    if (placed.length === 0) {
      return null;
    }
    const left = Math.min(...placed.map(([, at]) => at.x));
    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
    const top = Math.min(...placed.map(([, at]) => at.y));
    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
  }, [drawing, layout, heightOf]);

  const framed = useRef<string | null>(null);
  const justFramed = useRef(false);
  const centredOn = useRef<string | null>(null);

  // Frame the map when it is a different map — the first time it is drawn, and
  // again when a branch adds a claim to it. Panning, zooming and walking around
  // never re-frame: losing your place because the map was rearranged is the most
  // disorienting thing a canvas can do.
  useEffect(() => {
    // Only once the positions really are this map's. Framing from the positions
    // worked out for the map before the branch would frame the wrong thing, and
    // the right thing would then arrive underneath it.
    if (layout.runs === 0 || layout.laidOutFor !== mapKey || framed.current === mapKey) {
      return;
    }
    const frame = mapBounds();
    const room = surface.current?.getBoundingClientRect();
    if (frame === null || room === undefined) {
      return;
    }
    // Framed to fit — but never zoomed out past the point where a full tile would
    // have to become a summary. The reader's first sight of the map is tiles they
    // can read; if the whole map does not fit at that size, it is framed from its
    // beginning, on the left, where the map starts, and they pan to the rest.
    flow.setViewport(firstFrame(frame, { width: room.width, height: room.height }), {
      duration: 0,
    });
    framed.current = mapKey;
    justFramed.current = true;
  }, [layout.runs, layout.laidOutFor, flow, mapBounds, mapKey]);

  // The view follows whatever the keyboard is on, so a step along a wire never
  // walks off the edge of the glass. It does not fight the framing above: when a
  // branch has just arrived and moved focus to the claim it added, the whole map
  // has already been framed and that claim is in it.
  useEffect(() => {
    if (focused === null || layout.runs === 0 || centredOn.current === focused) {
      // Only when the keyboard has actually moved. Flipping between the two
      // worlds redraws every tile and moves none of them, and a view that slid
      // sideways on the flip would make the reader hunt for what changed — which
      // is the one thing the flip exists to show.
      return;
    }
    if (justFramed.current) {
      justFramed.current = false;
      centredOn.current = focused;
      return;
    }
    const node = flow.getNode(focused);
    if (node === undefined) {
      return;
    }
    centredOn.current = focused;
    flow.setCenter(node.position.x + TILE_WIDTH / 2, node.position.y + heightOf(focused) / 2, {
      zoom: flow.getZoom(),
      duration: 0,
    });
  }, [focused, flow, heightOf, layout.runs]);

  /** Show the claims a column had no room for, as a list. */
  const openColumn = useCallback(
    (layer: number) => {
      onOverflow({
        layer,
        claims: [...column.entries()].filter(([, at]) => at === layer).map(([id]) => id),
      });
      onStatus(`the claims in column ${layer}, as a list`);
    },
    [column, onOverflow, onStatus],
  );

  /**
   * What the reader just pointed at, or `null` when it was the empty map.
   *
   * Read off the page rather than from the drawing library, deliberately. The
   * library reports a click on a tile only through the machinery that also drags
   * tiles around, and tiles here do not drag — so that report never arrives.
   * Asking the page what was under the pointer is one line, and it gives the
   * same answer for a wire, a tile and the empty map.
   */
  const whatIsUnder = useCallback((target: HTMLElement | null): Selection => {
    const wire = target?.closest<HTMLElement>(".react-flow__edge");
    if (wire?.dataset.id !== undefined) {
      return { kind: "wire", id: wire.dataset.id };
    }
    const tile = target?.closest<HTMLElement>(".react-flow__node");
    if (tile?.dataset.id !== undefined) {
      return { kind: "claim", id: tile.dataset.id };
    }
    return null;
  }, []);

  /**
   * Fill the panel with whatever was pressed, or empty it on a press on the map.
   *
   * It listens for the press rather than the click, and that is not a detail:
   * the drawing library grabs the pointer on the surface the moment a press
   * begins, so that dragging the map keeps working when the pointer wanders off
   * a tile — and from then on every event, the click included, is reported
   * against the surface rather than against what was actually under the pointer.
   * The press is the last moment the page can still say what was pressed.
   */
  const onPointAt = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      const under = whatIsUnder(event.target as HTMLElement);
      // The zoom buttons and the library's own furniture are not the map.
      if (under === null && (event.target as HTMLElement).closest(".react-flow__controls")) {
        return;
      }
      if (under?.kind === "claim" && under.id.startsWith(OVERFLOW_PREFIX)) {
        openColumn(Number(under.id.slice(OVERFLOW_PREFIX.length)));
        return;
      }
      onSelect(under);
      if (under?.kind === "claim") {
        onFocused(under.id);
        // Pointing at a tile and reaching it with the keyboard land in the same
        // place, so the ring says where you are whichever way you got there.
        (event.target as HTMLElement)
          .closest<HTMLElement>(".react-flow__node")
          ?.focus({ preventScroll: true });
      }
    },
    [onSelect, whatIsUnder, onFocused, openColumn],
  );

  /**
   * Remember what the reader is on, fill the panel with it, and bring it into
   * view if it is off the edge of the screen.
   *
   * This catches the keyboard as well as the pointer. Reaching a claim or an
   * arrow with the keyboard and reaching it with the pointer do the same thing:
   * the panel beside the map reads it out. Nothing opens over the map, and
   * there is nothing to dismiss.
   */
  const onFocus = useCallback(
    (event: React.FocusEvent<HTMLDivElement>) => {
      const target = event.target as HTMLElement;
      const under = whatIsUnder(target);
      if (under === null) {
        return;
      }
      if (under.kind === "wire") {
        // **Landing on a wire does not select it, and that is not an
        // oversight.** The drawing library rebuilds a wire's element when it
        // becomes selected, and rebuilding the element the keyboard is standing
        // on drops focus to the page — which made tabbing through the map
        // impossible, because the wires come before the tiles. So a wire fills
        // the panel when you press Enter on it, and the focus is put back on the
        // rebuilt wire straight afterwards, which is what the effect below is
        // for. Pointing at one with the mouse is unchanged.
        return;
      }
      onSelect(under);
      onFocused(under.id);
    },
    [onSelect, whatIsUnder, onFocused],
  );

  // Where every tile ended up, in the shape moving along a wire needs: the
  // keyboard asks what it can *walk to*, which reads the whole map, feedback
  // arrows included.
  const places = useMemo(() => {
    const map = new Map<string, { x: number; y: number; height: number }>();
    for (const [id, at] of layout.positions) {
      map.set(id, { x: at.x, y: at.y, height: heightOf(id) });
    }
    return map;
  }, [layout, heightOf]);

  /**
   * Find a tile or a wire on the glass by the identifier it carries.
   *
   * By reading each element's own identifier rather than by asking the page for
   * a match: a wire is named after its two ends — `H->B` — and the arrow in the
   * middle of that is not a character an address for an element may contain.
   */
  const onTheGlass = useCallback((kind: "node" | "edge", id: string): HTMLElement | undefined => {
    const all = surface.current?.querySelectorAll<HTMLElement>(`.react-flow__${kind}`) ?? [];
    return [...all].find((one) => one.dataset.id === id);
  }, []);

  const claimWords = useCallback(
    (id: string) => world.claims.find((claim) => claim.id === id)?.claim ?? id,
    [world],
  );

  const onKeyDown = useMapKeys({
    wires: world.links,
    positions: places,
    focused,
    onFocused: (id) => {
      onFocused(id);
      // Reaching a tile with the keyboard and reaching it with the pointer do
      // the same thing: the panel beside the map reads it out. Nothing opens
      // over the map.
      onSelect({ kind: "claim", id });
      onTheGlass("node", id)?.focus();
    },
    onStatus,
    keys,
    words: claimWords,
  });

  // A wire the reader has just asked for, so that focus can be put back on it
  // once the drawing library has rebuilt it.
  const askedForWire = useRef<string | null>(null);

  // biome-ignore lint/correctness/useExhaustiveDependencies: the selection is not read inside — it is what this is waiting for. The wire is rebuilt because the selection changed, so the selection is exactly the right thing to hang this on.
  useEffect(() => {
    const id = askedForWire.current;
    if (id === null) {
      return;
    }
    askedForWire.current = null;
    // Two frames, not none. The drawing library keeps its own record of what is
    // selected and rebuilds the wire's element from it a frame later, so putting
    // focus back on the element that is there right now would put it on the one
    // about to be thrown away.
    const frame = requestAnimationFrame(() => {
      requestAnimationFrame(() => onTheGlass("edge", id)?.focus());
    });
    return () => cancelAnimationFrame(frame);
  }, [selection, onTheGlass]);

  // The keyboard map, bound once on the page. On the page rather than on the map
  // itself, because a key bound to the element you happen to be standing on is a
  // key that stops working the moment you press Tab — and every key below is left
  // alone while the keyboard is in a field.
  useEffect(() => {
    const onKey = (event: KeyboardEvent): void => {
      // A collapsed tile is reached with the keyboard like any other, and Enter
      // opens what is behind it — the same thing a press does.
      const target = event.target as HTMLElement | null;
      const at = target?.closest<HTMLElement>(".react-flow__node");
      if (event.key === "Enter" && at?.dataset.id?.startsWith(OVERFLOW_PREFIX) === true) {
        event.preventDefault();
        openColumn(Number(at.dataset.id.slice(OVERFLOW_PREFIX.length)));
        return;
      }
      // Enter on a wire reads it out in the panel beside the map — the same
      // thing pointing at it does. It is Enter rather than merely landing on it
      // because of what the comment above `onFocus` explains.
      const wire = target?.closest<HTMLElement>(".react-flow__edge");
      if ((event.key === "Enter" || event.key === " ") && wire?.dataset.id !== undefined) {
        event.preventDefault();
        askedForWire.current = wire.dataset.id;
        onSelect({ kind: "wire", id: wire.dataset.id });
        onStatus(`this arrow, read out in the panel beside the map`);
        return;
      }
      onKeyDown(event);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onKeyDown, openColumn, onSelect, onStatus]);

  return (
    <div
      className="canvas"
      ref={surface}
      data-arriving={arriving ? "yes" : "no"}
      onFocusCapture={onFocus}
      onPointerDownCapture={onPointAt}
    >
      <WireMarks />

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={TILE_TYPES}
        edgeTypes={WIRE_TYPES}
        // Tiles do not move. Automatic layout decides where a claim sits, and a
        // tile you can drag half of the time — snapping back whenever the map is
        // laid out again — reads as broken. Pinning, grouping and annotating
        // arrive later as things you ask for, not as free dragging.
        nodesDraggable={false}
        nodesConnectable={false}
        // A tile and a wire both answer to the pointer and to the keyboard. A
        // wire has to: everything it says on the glass it says again in words in
        // the panel, and the only way to ask for those words is to reach it.
        elementsSelectable={true}
        nodesFocusable={true}
        edgesFocusable={true}
        // Selecting a wire must not lift it above the others. The drawing
        // library's default is to re-sort the wires when one is selected so the
        // selected one draws on top — and re-sorting them moves the element the
        // keyboard is standing on, which drops focus to the page and makes
        // tabbing through the map impossible. Nothing here needs the lift: a
        // selected wire is marked by a ring, and how wires cross is settled by
        // routing rather than by drawing order.
        elevateNodesOnSelect={false}
        onNodeMouseEnter={(_, node) => setPointingAt(node.id)}
        onNodeMouseLeave={() => setPointingAt(null)}
        // As far out as the map goes, and no further: past this the summary
        // tile's words would be drawn smaller than anything in this product is
        // allowed to be.
        minZoom={SMALLEST_ZOOM}
        maxZoom={LARGEST_ZOOM}
        proOptions={{ hideAttribution: false }}
        // Named, not addressed: the drawing library writes the address around
        // the name itself.
        defaultEdgeOptions={{ markerEnd: ARROWHEAD }}
      >
        <Background variant={BackgroundVariant.Dots} gap={32} size={1} />
        <Controls showInteractive={false} position="bottom-left" />
      </ReactFlow>

      {layout.failure === null ? null : (
        <p className="canvas__failure">{`The map could not be laid out. ${layout.failure}`}</p>
      )}
    </div>
  );
}

/** What the map needs to be dropped into a page. */
export type MapCanvasProps = SurfaceProps;

/** The map, ready to be dropped into a page. */
export function MapCanvas(props: MapCanvasProps) {
  return (
    <ReactFlowProvider>
      <MapSurface {...props} />
    </ReactFlowProvider>
  );
}

/**
 * A claim, as a card on the map.
 *
 * A tile shows six things and no more, because a seventh always arrives at the
 * cost of the six:
 *
 *   1. the claim, wrapping to three lines and then stopping — never cut in the
 *      middle of a word;
 *   2. three belief chips, the model's, the reader's and a market's, side by
 *      side and never averaged;
 *   3. at most two evidence clippings, each a letter standing for a publication
 *      and one line of what it says;
 *   4. the day the claim is settled by;
 *   5. its outline, which says what kind of claim it is — shape carries that,
 *      never colour;
 *   6. a place for its badges, which arrive with the buttons that earn them.
 *
 * The rest — the full claim, the resolution criteria, the sources, the
 * reasoning behind a number — belongs in the panel beside the map, which is
 * built in the pull request after this one.
 *
 * **The outline is drawn rather than bordered.** The tile has no border of its
 * own; a line drawing sits behind it with a one-pixel stroke at a tenth of the
 * text colour, and its path is what makes a hypothesis look different from a
 * dead end. Four shapes, four kinds, and the shapes survive being printed in
 * grey — which a colour never does.
 */

import { Handle, Position, useStore } from "@xyflow/react";
import { toDay } from "../graph/diff/days";
import { claimLines, SUMMARY_BELOW_ZOOM, TILE_WIDTH, tileHeight } from "../graph/geometry";
import type { Badge, ClaimKind, ClaimView } from "../world";
import { BeliefChip } from "./BeliefChip";
import "./tile.css";

/**
 * The four outlines, as line drawings the width and height of a tile.
 *
 * Each one is drawn to the height its own tile turned out to be, because a tile
 * is as tall as its content. Every path is offset by half a pixel so that a
 * one-pixel stroke lands on a pixel boundary instead of straddling two and
 * going soft.
 *
 * - **hypothesis** — the left edge comes to a point. This is where the map
 *   starts: the claim the reader typed, with nothing before it.
 * - **event** — an ordinary rounded box. A step in the middle of the chain.
 * - **market** — the top right corner is cut away, the way a ticket is. There
 *   is something here you could actually trade.
 * - **not tradeable** — the right edge is notched inward. The chain really does
 *   end here, and there is nothing to plug into it.
 *
 * Two of the four cut into the space a word would sit in, so those two tiles are
 * given a wider margin on that side — see `tile.css`. A shape that crosses its
 * own words is not a shape, it is a mistake.
 */
const OUTLINES: Record<ClaimKind, (height: number) => string> = {
  hypothesis: (h) => `M 16.5 0.5 H ${TILE_WIDTH - 0.5} V ${h - 0.5} H 16.5 L 0.5 ${h / 2} Z`,
  event: (h) =>
    `M 6.5 0.5 H ${TILE_WIDTH - 6.5} A 6 6 0 0 1 ${TILE_WIDTH - 0.5} 6.5 V ${h - 6.5} ` +
    `A 6 6 0 0 1 ${TILE_WIDTH - 6.5} ${h - 0.5} H 6.5 A 6 6 0 0 1 0.5 ${h - 6.5} ` +
    `V 6.5 A 6 6 0 0 1 6.5 0.5 Z`,
  market: (h) => `M 0.5 0.5 H ${TILE_WIDTH - 18.5} L ${TILE_WIDTH - 0.5} 18.5 V ${h - 0.5} H 0.5 Z`,
  not_tradeable: (h) =>
    `M 0.5 0.5 H ${TILE_WIDTH - 0.5} V ${h / 2 - 14} L ${TILE_WIDTH - 14.5} ${h / 2} ` +
    `L ${TILE_WIDTH - 0.5} ${h / 2 + 14} V ${h - 0.5} H 0.5 Z`,
};

/** What each kind is called on screen. No underscores and no code names. */
const KIND_WORDS: Record<ClaimKind, string> = {
  hypothesis: "hypothesis",
  event: "event",
  market: "market",
  not_tradeable: "not tradeable",
};

/**
 * What an edit did to this claim, in the words a reader hears rather than the
 * word the code uses. Read out before the claim itself, so a reader who never
 * sees the tile learns the same thing first.
 */
const DIFF_WORDS: Record<string, string> = {
  added: "added by your edit",
  killed: "supposed false by your edit",
  downstream: "your edit can reach this",
  untouched: "your edit cannot reach this",
};

/** One published item, as a clipping: a letter for the publication and one line. */
function Clipping({
  monogram,
  host,
  line,
  direction,
}: {
  monogram: string;
  host: string;
  line: string;
  direction: 1 | -1;
}) {
  // A sign, not a colour: "+" for an item that supports the claim, "−" for one
  // that cuts against it. A reader who cannot tell two hues apart loses nothing.
  const sign = direction === 1 ? "+" : "−";
  const inWords = direction === 1 ? "supports this claim" : "cuts against this claim";
  return (
    <li className="tile__clipping">
      <span className="tile__monogram" aria-hidden="true">
        {monogram}
      </span>
      <span className="tile__clipping-sign" aria-hidden="true">
        {sign}
      </span>
      <span className="tile__clipping-line">
        <span className="tile__hidden">{`${host}, ${inWords}: `}</span>
        {line}
      </span>
    </li>
  );
}

/**
 * What a claim's tile says about the edits behind it, in the order they were
 * made.
 *
 * Two badges in a row are drawn as a sequence with an arrow between them, which
 * is the whole point of UX-14: *Supposed · Oct 1 → Retracted · Oct 2 · by "a
 * confirmed military strike on Iranian territory"*. Met as a sequence the rule
 * that a later edit outranks an earlier supposition is obvious; met as a number
 * that moved on its own it reads as a bug.
 *
 * Every badge is also a thing the keyboard can land on, because each one carries
 * a sentence saying what it means, and a reason you cannot reach is not a reason.
 */
function Badges({ badges }: { badges: readonly Badge[] }) {
  if (badges.length === 0) {
    return null;
  }
  return (
    <p className="tile__badges">
      {badges.map((badge, index) => (
        <span className="tile__badge-run" key={badge.words}>
          {index === 0 ? null : (
            <span className="tile__badge-arrow" aria-hidden="true">
              {" → "}
            </span>
          )}
          <button className="tile__badge" type="button" title={badge.reason}>
            <span className="tile__hidden">{`${badge.reason} `}</span>
            <span className="tile__badge-words">{badge.words}</span>
          </button>
        </span>
      ))}
    </p>
  );
}

/** What a tile needs to draw itself. */
export interface TileProps {
  /** The claim this tile is for. */
  readonly claim: ClaimView;
  /** True when this claim is the one the reader started from. */
  readonly isHypothesis: boolean;
  /**
   * How many versions of the map were run to produce this world's numbers.
   *
   * Absent means nothing computed them, and the model chip says so instead of
   * describing a run that never happened.
   */
  readonly versions?: number;
  /**
   * The height the map reserved for this tile.
   *
   * Usually the same as the tile's own content needs. It differs only in a
   * diff, where one box has to hold whichever of the two paintings is taller, so
   * that flipping between them moves nothing.
   */
  readonly height?: number;
}

/** One claim's tile. */
export function Tile({ claim, isHypothesis, versions, height: reserved }: TileProps) {
  // How far the map is zoomed out. Below the threshold a tile stops showing
  // everything and shows a summary instead — the claim and the three chips —
  // because the alternative is type too small to read. The tile changes what it
  // draws; it never shrinks what it draws.
  const zoom = useStore((state) => state.transform[2]);
  const detail = zoom < SUMMARY_BELOW_ZOOM ? "summary" : "full";

  // Only one claim in four prints why it has no market: the kind that ends the
  // map without an instrument. That reason is a finding — somebody looked and
  // wrote down what they found — and it belongs on the face of the tile. For
  // every other claim "no market" is a fact about the world's plumbing, the
  // chip says it in two words, and the sentence behind it is on the chip's
  // shelf and in what the chip is called when it is read out loud.
  const finding = claim.kind === "not_tradeable" ? claim.beliefs.market.absence : undefined;
  // As tall as this claim's own content, worked out the same way the layout
  // worked it out, so the box the map reserved and the box the browser draws
  // are the same box.
  const height = reserved ?? tileHeight(claim);
  const lines = claimLines(claim.claim);
  // The foot only exists when it has something in it. An empty one would still
  // take a gap above it, and the tile would have a step of dead space at the
  // bottom — which is the whole thing a clamped height is meant to avoid. When
  // the badges arrive, having one of those puts the foot there too.
  const badges = claim.badges ?? [];
  const hasFoot = finding !== undefined || claim.evidence.length > 0 || badges.length > 0;
  // What an edit did to this claim, said in words before the claim itself for a
  // reader who never sees the tile. Absent on a map nobody has edited.
  const diffWords = claim.diff === undefined ? "" : `${DIFF_WORDS[claim.diff] ?? claim.diff}. `;

  return (
    <article
      className="tile"
      data-kind={claim.kind}
      data-detail={detail}
      data-hypothesis={isHypothesis ? "yes" : "no"}
      data-diff={claim.diff ?? "none"}
      style={{
        width: `${TILE_WIDTH}px`,
        height: `${height}px`,
        // How many lines of the claim to show. The same number the height was
        // worked out from, so the claim stops exactly where the box ends.
        ["--tile-claim-lines" as string]: `${lines}`,
      }}
      aria-label={`${diffWords}${KIND_WORDS[claim.kind]}: ${claim.claim}`}
    >
      <svg
        className="tile__outline"
        width={TILE_WIDTH}
        height={height}
        viewBox={`0 0 ${TILE_WIDTH} ${height}`}
        aria-hidden="true"
        focusable="false"
      >
        <path d={OUTLINES[claim.kind](height)} />
      </svg>

      {/* The sockets. An arrow that fires once and an arrow that has to keep
          holding are different claims about the world, so they arrive at
          different sockets and leave from different sockets — what a wire means
          is visible where it lands, before you follow it anywhere. */}
      <Handle
        type="target"
        position={Position.Left}
        id="in-trigger"
        className="tile__port tile__port--trigger"
        style={{ top: "38%" }}
      />
      <Handle
        type="target"
        position={Position.Left}
        id="in-sustain"
        className="tile__port tile__port--sustain"
        style={{ top: "62%" }}
      />
      <Handle
        type="source"
        position={Position.Right}
        id="out-trigger"
        className="tile__port tile__port--trigger"
        style={{ top: "38%" }}
      />
      <Handle
        type="source"
        position={Position.Right}
        id="out-sustain"
        className="tile__port tile__port--sustain"
        style={{ top: "62%" }}
      />

      <header className="tile__header">
        <span className="tile__kind">{KIND_WORDS[claim.kind]}</span>
        <time className="tile__resolves" dateTime={claim.resolvesBy}>
          {`resolves ${toDay(claim.resolvesBy)}`}
        </time>
      </header>

      <p className="tile__claim">{claim.claim}</p>

      <div className="tile__beliefs">
        <BeliefChip
          owner="model"
          slot={claim.beliefs.model}
          standing={claim.standing}
          versions={versions}
        />
        <BeliefChip owner="user" slot={claim.beliefs.user} />
        <BeliefChip owner="market" slot={claim.beliefs.market} />
      </div>

      {detail === "full" && hasFoot ? (
        // The foot of the tile. It is pushed to the bottom edge as one block, so
        // that on every tile alike the claim is at the top, the beliefs are in
        // the middle and whatever is left sits on the floor — and the eye can
        // read down a column without hunting for the line it wants.
        <div className="tile__foot">
          {finding === undefined ? null : <p className="tile__absence">{finding.reason}</p>}

          {claim.evidence.length === 0 ? null : (
            <ul className="tile__clippings">
              {claim.evidence.map((item) => (
                <Clipping
                  key={item.line}
                  monogram={item.monogram}
                  host={item.host}
                  line={item.line}
                  direction={item.direction}
                />
              ))}
            </ul>
          )}

          {/* What the edits behind this claim did to it, in order. Empty on a
              map nobody has edited, and then it takes no room at all. */}
          <Badges badges={badges} />
        </div>
      ) : null}
    </article>
  );
}

/**
 * Which way the money moves — the only thing in this product that is allowed to
 * be a hue, and never a hue by itself.
 *
 * `--dir-up` is blue and `--dir-down` is amber. Never red and green: red-green
 * fails the most common form of colour blindness, and the loss-and-gain reading
 * is wrong half the time — a falling oil price is good news for an airline.
 *
 * **This is the one component that reads those two colours.** Everything else in
 * the tree is forbidden to name them, and a test checks that. The reason is not
 * tidiness: a direction has to carry a glyph *and* a sign *and* a word as well
 * as a hue, and the moment a second component reaches for the colour on its own,
 * one of those three gets dropped and the picture starts saying something by
 * hue alone.
 *
 * **The trap this component exists to prevent, and it is a live one.** The arrow
 * from *the strait reopens* to *Brent crude settles below $68* is `+1.6` —
 * positive, because it makes that claim come out **true** more often — and the
 * thing that claim describes is a **falling** price. Colour that arrow amber and
 * you have said the opposite of what it means. **A push's sign is not a
 * direction of financial effect.** A push is carried by its printed sign and by
 * the word *toward* or *against*, and never by one of these two hues.
 *
 * **Nothing in this build renders one.** There is no thesis card, no strip of
 * world state, no live price, and the ranked list of what moved needs the
 * engine. The component and its two colours are written now anyway, so that two
 * unused tokens cannot be quietly borrowed for something else in the meantime.
 */

import "./directionReadout.css";

/** Which way the money moves. */
export type Direction = "up" | "down";

/** What the readout needs to draw itself. */
export interface DirectionReadoutProps {
  /** Which way the money moves. */
  readonly direction: Direction;
  /**
   * How far, already written out the way this product writes a number — the
   * readout prints it as given and works nothing out.
   */
  readonly amount: string;
  /** What moved, in the words the reader would use for it. */
  readonly what: string;
}

/** The glyph, the sign and the word that go with each direction. */
const READINGS = {
  up: { glyph: "▲", sign: "+", word: "up" },
  down: { glyph: "▼", sign: "−", word: "down" },
} as const;

/** Which way the money moves: a glyph, a sign, a word and a hue — all four. */
export function DirectionReadout({ direction, amount, what }: DirectionReadoutProps) {
  const reading = READINGS[direction];
  return (
    <span className="direction-readout" data-direction={direction}>
      <span className="direction-readout__glyph" aria-hidden="true">
        {reading.glyph}
      </span>
      <span className="direction-readout__amount">{`${reading.sign}${amount}`}</span>
      <span className="direction-readout__word">{reading.word}</span>
      <span className="direction-readout__what">{what}</span>
    </span>
  );
}

