1	/**
2	 * The one end-to-end test: the stored example, opened and edited, **by keyboard
3	 * alone**.
4	 *
5	 * It is the only test in this product that drives a real browser against a real
6	 * server, so it is spent on the one claim nothing else can make: that the two
7	 * halves, started the way a person starts them, draw the stored example — and
8	 * that the three things the interface exists to say are on the screen.
9	 *
10	 * 1. **The map draws**, from the server's own copy of the example. Nothing on it
11	 *    is typed into the browser.
12	 * 2. **Opening the strike branch changes what the claims say, and OPEC+'s
13	 *    announcement does not change.** That is the product's central correctness
14	 *    claim — *here is what your edit can reach, and here is what it provably
15	 *    cannot* — and it is checked here against the server's own branch rather
16	 *    than against a shape a test wrote out.
17	 * 3. **The hypothesis says its supposition was overridden**, word for word:
18	 *    *Supposed · Oct 1 → Retracted · Oct 2 · by "a confirmed military strike on
19	 *    Iranian territory"*.
20	 *
21	 * **The whole walk is done with the keyboard**, and that is not a flourish: it
22	 * is the check that the interface is usable without a mouse end to end. Every
23	 * step below is a keystroke a reader could make.
24	 *
25	 * It needs no model key. The screen it drives is fed by a stored example, which
26	 * calls nothing.
27	 */
28	
29	import { expect, type Page, test } from "@playwright/test";
30	
31	/**
32	 * Wait until the map has been laid out.
33	 *
34	 * Where the tiles go is worked out on a background thread, so for a moment after
35	 * the map appears every tile is still stacked in the same place. Waiting for the
36	 * tiles to be somewhere is the honest signal that the layout has landed —
37	 * waiting a fixed number of milliseconds is a guess that is wrong on a slow
38	 * machine.
39	 */
40	async function waitForTheLayout(page: Page): Promise<void> {
41	  await expect
42	    .poll(
43	      () =>
44	        page
45	          .locator(".react-flow__node")
46	          .evaluateAll(
47	            (nodes) => new Set(nodes.map((node) => (node as HTMLElement).style.transform)).size,
48	          ),
49	      { timeout: 30_000, message: "the map was never laid out" },
50	    )
51	    .toBeGreaterThan(1);
52	}
53	
54	/** Which claim the keyboard is standing on, or nothing when it is off the map. */
55	function standingOn(page: Page): Promise<string | undefined> {
56	  return page.evaluate(
57	    () => document.activeElement?.closest<HTMLElement>(".react-flow__node")?.dataset.id,
58	  );
59	}
60	
61	/**
62	 * Press Tab until the keyboard is on the map, and say which claim it landed on.
63	 *
64	 * **The map is one stop in the page's tab order and then its own keys take
65	 * over** — j and k down and up a column, h and l along the wires. That is the
66	 * design rather than a shortfall: eight tiles and twenty-four chips as separate
67	 * tab stops would make Tab the slowest way to cross the map, and the line under
68	 * the map says which keys to use instead from the moment it opens.
69	 */
70	async function tabOntoTheMap(page: Page): Promise<string> {
71	  for (let press = 0; press < 40; press += 1) {
72	    await page.keyboard.press("Tab");
73	    const at = await standingOn(page);
74	    if (at !== undefined) {
75	      return at;
76	    }
77	  }
78	  throw new Error("Tab never reached the map; it is not reachable by keyboard.");
79	}
80	
81	/**
82	 * What the hypothesis's tile must read, word for word, once the strike lands.
83	 *
84	 * Two badges with an arrow drawn between them, which is what makes the rule read
85	 * as a sequence: you supposed the strait reopens, and a later edit pushed it back
86	 * down. Each badge also carries the sentence behind it for a reader who is not
87	 * looking at the tile, and that sentence is not part of what is drawn.
88	 */
89	const OVERRIDDEN = [
90	  "Supposed · Oct 1",
91	  'Retracted · Oct 2 · by "a confirmed military strike on Iranian territory"',
92	];
93	
94	test("the stored example, opened and edited by keyboard alone", async ({ page }) => {
95	  await page.goto("/");
96	
97	  // The launchpad, reached and opened with the keyboard. Tab to the one example
98	  // that is live and press Enter.
99	  const hormuz = page.getByRole("button", { name: /Strait of Hormuz/ }).first();
100	  await hormuz.focus();
101	  await expect(hormuz).toBeFocused();
102	  await page.keyboard.press("Enter");
103	
104	  // The map draws, from the server's own copy of the example.
105	  await expect(page.locator(".react-flow__node").first()).toBeVisible();
106	  await expect(page.locator('.react-flow__node[data-id="H"]')).toBeVisible();
107	  await expect(page.locator(".map-origin")).toContainText("/api/fixtures/hormuz");
108	  await waitForTheLayout(page);
109	  const drawn = await page.locator(".react-flow__node").count();
110	  expect(drawn).toBe(7);
111	
112	  // Every tile is a whole tile on the first frame, not a summary. The zoom is
113	  // held at the point where a tile's smallest words land at eleven pixels, and
114	  // below that a tile changes what it draws rather than shrinking it.
115	  const details = await page
116	    .locator(".tile")
117	    .evaluateAll((tiles) => tiles.map((tile) => (tile as HTMLElement).dataset.detail));
118	  expect(new Set(details)).toEqual(new Set(["full"]));
119	
120	  // A tile is 280 pixels wide, measured rather than eyeballed.
121	  const width = await page.evaluate(() => {
122	    const tile = document.querySelector(".tile");
123	    const view = document.querySelector<HTMLElement>(".react-flow__viewport");
124	    const zoom = Number(/scale\(([0-9.]+)\)/.exec(view?.style.transform ?? "")?.[1] ?? 1);
125	    return (tile?.getBoundingClientRect().width ?? 0) / zoom;
126	  });
127	  expect(Math.round(width)).toBe(280);
128	
129	  // Every key, on one sheet — and it says out loud that tiles do not move.
130	  await page.keyboard.press("?");
131	  await expect(page.getByText(/Tiles do not move/)).toBeVisible();
132	  // Escape closes it, and nothing was left half-done.
133	  await page.keyboard.press("Escape");
134	  await expect(page.getByText(/Tiles do not move/)).toBeHidden();
135	
136	  // Walking the wires. Tab onto the map, step forward along a wire out of the
137	  // hypothesis, and the line under the map names the wire that was taken.
138	  await page.evaluate(() => document.body.focus());
139	  const entered = await tabOntoTheMap(page);
140	  expect(entered).toBe("H");
141	  await page.keyboard.press("l");
142	  await expect(page.locator(".map-status")).toContainText("along an arrow");
143	  // Whatever it landed on is one of the three claims the strait's opening
144	  // causes. Which one it is falls out of which is nearest on the glass, and that
145	  // rule is checked over every claim and both directions in
146	  // `src/keyboard/__tests__/focusMap.test.ts`.
147	  const landed = await standingOn(page);
148	  expect(["B", "C", "N1"]).toContain(landed);
149	
150	  // And back along a wire, toward what causes it.
151	  await page.keyboard.press("h");
152	  await expect(page.locator(".map-status")).toContainText("along an arrow");
153	  expect(["H", "C", "R"]).toContain(await standingOn(page));
154	
155	  // Down the column, which is about the picture rather than about the wires.
156	  await page.keyboard.press("j");
157	  await expect(page.locator(".map-status")).toContainText("column");
158	
159	  // The command palette, by name, and the branch opened through it — so the
160	  // whole of what follows is reachable without a mouse.
161	  // What the claim the branch cannot reach reads BEFORE the branch is opened. The
162	  // test compares against this rather than against a number typed in here: the
163	  // stored example's numbers are curated and have already changed once, and the
164	  // claim being made is "the same number as before", not "this particular number".
165	  const opecBefore = await page
166	    .locator('.react-flow__node[data-id="R"] .belief-chip__reading')
167	    .first()
168	    .innerText();
169	  expect(opecBefore).toMatch(/^\.\d+$/);
170	
171	  await page.keyboard.press("Meta+k");
172	  await expect(page.getByText(/Every command, by name/)).toBeVisible();
173	  await page.keyboard.type("Hormuz opens");
174	  await page.keyboard.press("Enter");
175	  // The union of the two worlds is laid out again, once, before anything on it
176	  // can be read.
177	  await expect(page.locator('.react-flow__node[data-id="S"]')).toBeVisible();
178	  await waitForTheLayout(page);
179	
180	  // The branch is open. The map says which branch and which of the two worlds is
181	  // in front, and the line under it says what the branch did — with no number,
182	  // because nothing computed one.
183	  await expect(page.locator(".map-bar__where")).toContainText("Hormuz opens, then Iran is struck");
184	  await expect(page.locator(".map-live")).toHaveText(
185	    "Branch created. One claim added, six claims your edit can reach, one supposition " +
186	      "retracted. No numbers yet.",
187	  );
188	
189	  // The claim the branch added is on the map, with the two badges its edits
190	  // earned, in the order they were made.
191	  const strike = page.locator('.react-flow__node[data-id="S"]');
192	  await expect(strike).toBeVisible();
193	  await expect(strike).toContainText("A confirmed military strike on Iranian territory.");
194	  await expect(strike.locator(".tile__badge-words")).toHaveText(["Added", "Supposed · Oct 2"]);
195	  // And while a claim is supposed, its tile shows the word where a likelihood
196	  // would go — never `1.0`, and never `.98`.
197	  await expect(strike.locator(".belief-chip__figure").first()).toHaveText("Supposed · Oct 2");
198	
199	  // The hypothesis: the overridden supposition, word for word.
200	  const hypothesis = page.locator('.react-flow__node[data-id="H"]');
201	  await expect(hypothesis.locator(".tile__badge-words")).toHaveText(OVERRIDDEN);
202	  await expect(hypothesis.locator(".tile__badge-arrow")).toHaveText("→");
203	  // And it shows the absence where its likelihood was, because the edit can
204	  // reach it and nothing has worked the new number out.
